(window.__SYN=window.__SYN||{})[5]=[{"d":1,"t":["استشهاد القديس إسطفانوس رئيس الشمامسة","استشهاد القديس لأونديانوس","استشهاد القديسين ديوسقوروس وأخيه سكلابيوس"],"b":"في مشل هذا اليوم من سنة استشهد القديس العظيم إسطفانوس رئيس الشمامسة وأول الشهداء» وكان قد اختير مع ستة شمامسة آخرين مملوئين من الروح القدس والحكمة لعمل الشماسية وخدمة الفقراء ”\".\nوكان إسطفانوس يعظ وبصنع عجائب عظيمة في الشعب \".\nوقد أثارت شخصيته ومعجزاته حسد ومقاومة مواطنيه من اليهود اليونانيين الذين لم يقدروا أن يقاوموا الروح والحكمة التى كان يتكلم بهاء فخطفوه وأتوا به إلى مجمعهم واتهموه بأنه يجدف ضد الهيكل والناموس. فوقف إسطفانوس بينهم وعرض في ضورة تاريخية عميقة ومستفيضة» وكانت كلماته )0 أع خب بحلا )0 أع تر ايف وجهه كأنه وجه ماداك 0 ثم هجموا عليه واحدة وأخرجوه خارج المدينة ورجموه وهو يدعو \" أيها الرب يسوع اقبل روحي ' '. ورأى مجد يسوع قائما عن يمين الله. ثم جثا على ركبتيه وصرخ بصوت عظيم قائلا ' يارب لا ثقم لحم هذه الخطية \". وإذ قال هذا رقد 9 . وجمل المؤمنون جسده الطاهر ودفنوه بإكرام جزيل.\nبركة صلواته فلتكن معنا. آمين.\n\" - وفيه أيضا استشهد القديس لاونديانوس السوري في عهد الملك مكسيميانوس الذي استدعى القديس» ووعده بأموال كثيرة لكي ينكر إيمانه بالسيد المسيح ولكن القديس رفض متمسكا فغضب الملك وأمر بعصره في الهنبازين) ثم ضربه ثم طرحه في زيت وشحم مغلي. أما القديس فكان صابرا على هذه العذابات وكان الرب يسوع يقويه ويقيمه ولما ضجر الملك من تعذيبه أمر بقطع رأسه ونال كليل الشهادة وأظهر الرب من جسده آيات كثيرة» حتى شاع ذكره في كل سوريا وبنوا على امه كنائس كثيرة.\nبركة صلواته فلتكن معنا. آمين.\n- وفيه أيضا من سنة 10 للشهداء ( 4 ام ) استشهد القديسان ديوسقوروس وأخيه سكلابيوس. كان هذان القديسان ابني أرخن محب لله من مدينة أخميم يدعى أمونيوس » وكان غنيا جدا وقد اهتم بتربية ولديه. ولما بلغا سن الشباب مضيا إلى جبل أخميم؛ على يدي عابد قديس يدعى القس مويسيس كان يقيم بجوار عين ماء. وبعد قليل إذ شعر القديس بقرب نياحته استدعاها بالثبات على الإيمان وحفظ وصايا الرب» ثم باركهما وفاضت روحه الطاهرة. فكفناه بإكرام جزيل وعاشا بعده ف جهاد : رو حي ونسك وصلاة ومقاومة روب الشياطين ونزل القديسان يوما إلى مدينة نة أخميم ليبتاعا ما يحتاجان إليه ؛ : فأمسكهما أهمل المدينة ومضوا هما إلى إ لأسقف فرسم ديوسقوروس قسا وسكلابيوس شماسا ولما عادا إلى لجل اجتمع حولهما كثير من الإخوة ليتتلمذوا على أيديهماء كما كنيسة صغيرة بالجبل تحولت إلى مركز روحي حي.\nالله موهبة شفاء الأمراض وإخراج الشياطين. وقد عاش هذان القديسان في هذه البرية نحو خمس وأربعين سنة مع الإخوة بفرح شديد يمارسون حياة التسبيح كأنهم في الفردوس.\nالأنبا أوضاكيوس أسقف أخميم البرية واجتمع بهماء فشجعهما أن يثبتا على الإبمان واحتمال الاضطهاد الذي سيحل بهما بفرح.\nأنصنا وعرض على المسيحيين عبادة الأوثان فظهر رئيس الملائكة ميخائيل للقديسين ديوسقوروس وسكلابيوس ودعاهما للنزول من الجبل ليشهدا للسيد المسيح في أخميم وينالا كال الشهادة 0 ممم ففرحا بهذه الدعوة وأقاما رئيسا للإخوة يدعى بطرس عوضا وبعد نزولهما ظلا يشجعان المسيحيين على تحمل الآلام؛ فسمع الوالي خبرهما واستدعاهما وأمر بسجنهما وي الصباح عرض عليهما الوالي التبخير للأوثان فأجاباه قائلين \" نحن لا للآلمة ولا ننسى الذين قدموا أرواحهم للسيد المسيح؛ فقد كنا نراها صاعدة أمامنا إلى السماء ونحن على استعداد أن نوت مثلهم» ومهما أردت أن تفعل فاصنع بنا لنلحق بإخوتنا \".\nفغضب الوالي وأمر بتعذييهماء ثم وضعهما في حبس وكان أربعون جنديا على رأسهم أكوديوس وفليمون. وفي منتصف الليل ظهر ملاك الرب للقديس ديوسقوروس وقال له:\nقم صل فإن أكوديوس وفليمون وجنودهما سوف يسبقونكما تقدمة لك في هذه المدينة\" فظن القديس أن أحد الإخوة هو الذي يكلمه فقال له \" كيف أقدر على القيام الآن؟ \" فأجابه الملاك: \" قم وصل لأن الرب يجل المقبدين \". وللوقت انخلت التي كان مقبدا مها وكذا قود - جميع المعترفين. فقاموا جيعا الله وكان نور سماوي يضيء عل أكوديوس وفليمون.\nفلما شاهد الجنود هذا كله ذهبوا إل إريانوس واعترفوا بالسيذ المسيح فأمر بقطع رؤوسهم جيعا» وبعد ذلك أمر الوالي بقطع رأسي القديسين ديوسقوروس وسكلابيوس فنالا إكليل الشهادة.\nويوجد دير باسميهما في جبل أخميم و يشتهر باسم دير الشهداء.\nبركة صلواتهما فلتكن معنا. ولربنا المجد دائما أبديا آمين."},{"d":2,"t":["نياحة الأنبا اؤناس البطريرك السادس عشر من بطاركة الكرازة المرقسية","استشهاد القديس غللينيكوس أسقف أوسيم","نياحة القديس الأنبا يونا"],"b":"اعد بد مدع - في مثل هذا اليوم من سنة 7 للشهداء »( م ) تنح البطريرك القديس الأنبا اؤناس بابا الإسكندرية السادس عشر وقد أقيم بطريركا أ كيهك الموافق ) رؤة نوفمبر 17 م كان رجلا عالما تق وديعا محا للجميع 6 شيد كنيسة باسم القديسة العذراء مريم بالإسكندرية ليصلى فيها المؤمنون إذ كانوا في ذلك الوقت في البيوت والمغاير بسبب الاضطهاد الوثنى للكنيسة وقد امن كثيرون بالسيد المسيح على يديه وعمدهم 4 وف عهده ظهر سابيليوس المبتدغ الذي أنكر الأقانيم الثلاثة وكان يعلم أن الآب وا لابن والروح القدس أقنوم واحد وقد حرمه الثابا ' وأبطل قوله بالبراهين المقنعة من الكتب المقدسة.\nولما أكمل سعيه الصالح تنيح بسلام ودفن بدير المغارة بركة صلواته فلتكن معنا. آمين.\nان وفيه 1 يضا “من سنة 7 للشهد إ ء ل اي 1 4 إ ستشهد القد يس أسقف أوسيم 0 . كان ن يعلم شعبه ويدعوهم '؟ دير الغارة هو الكنيسة المرقسية بالإسكندرية حاليا.\nافاي بإيمانهم القويم رافضا عبادة الأوثان والتبخير لها. ولما علم الإمبراطور دقلديانوس أرسل جنوده للقبض عليه » فجمع شعبه في الكنيسة وصلى القداس وناوهم من الأسرار المقدسة؛ ثم سلم نفسه للجند بين دموع شعبه» فأخذه الجند إلى الوالي الذي عذبه بشدة؛ وكان الرب يشفيه ويعزيه» ثم أمر الوالي أن نشق يده إلى كتفه» ففاضت روحه الطاهرة من كثرة العذابات ونال إكليل الشهادة» فطرح الجند جسده على تل وأرشد الرب بعض المؤمنين فجاءوا وأخذوا اللجسد وكفنوه ودفنوه بإكرام بركة صلواته فلتكن معنا. آمين.\n- وفيه أيضا تنيح القديس الناسك الأنبا يوناء عاش هذا القديس بأحد أديرة حاجر أرمنت وكان يجهد نفسه في أصوام ونسك وقد أعطاه رب المجد موهبة إخراج الشياطين وشفاء المرضى. ولما ربت نياحته ظهر له بعض القديسين يدعونه للفرح الأبدي :\nثم رقد في الرب عن عمر يناهز السبعين عاما. . فحزن عليه الرهبان» وجاء أسقف المدينة وصلى عليه» ودفنوه بجوار كنيسة الدير بإكرام جزيل.\nبركة صلواته فلتكن معنا.\nولربنا المجد دائما أبديا آمين.\n)0 أوسيم: مديئة ومركز تابع لمحافظة الجيزة."},{"d":3,"t":["استشهاد أطفال بيت لحم"],"b":"في مثل هذا اليوم من السنة الثانية لميلاد الرب يسوع» أتى المجوس من المشرق إلى أورشليم» وذهبوا إلى قصر هيرودس الملك يبحثون عن المولود قائلين \"© \" أين هو المولود ملك اليهود» فإننا رأينا نجمه في المشرق وأتينا لتسجد له \". فلما مع هيرودس اضطرب وكل | أورشليم معه» وجمع الكهنة وسألهم \" أين يولد المسيح؟\". فقالوا له ' في بيت لحم حسب نبوة ميخا الني» وأنت يا بيت لحم أرض يهوذا لست الصغرى بين ولايات يهوذا لأن منك يخرج مدبر يرعى شعبى ”\". فأرسل هيرودس المجوس إلى بيت لحم قائلا \" اذهبوا عن الصبي ومتى وجدتموه أخبروني لكي التي أنا أيضا وأسجد له \". وكان يقصد بذلك أن يذهب ليقتل الصي.\nفذهب المجوس ل بيت لحم والنجم يتقدمهم إلى حيث الموضع الذي كان الطفل مضجعا فيه؛ فلما وصلوا سجدوا للطفل وقدموا هدايا ذهبا ولبانا ومرا. اشم أوجى إليهم أ آلا يرجعوا إلى هيردوس في طريق أخرى إلى كورتهم.\nتحير 0 ميخا ه: ؟\nلما رأى همبرودس أن المجوس سخروا به غضب جدا 6 وأرسل جنوده وقتل جميع الأطفال الذين في بيت لحم من ابن سنتين ' فما دون بحسب الزمان الذي تحققه من المجورس» لكى يتم ما قيل صوت سمع ج الرامة نوح وبكاء وعويل كثير 6 تبكي على أولادها ولا تريد أن تتعزى لأنمم ليسوا \"\". وذلك لأن قبر راحيل زوجة يعقوب كان بالقرب من لحم بركة شفاعة هؤلاء الأطفال الشهداء فلتكن معنا.\nولربنا المجد دائما أبديا آمين."},{"d":4,"t":["نياحة القديس يوحنا الإنجيلي"],"b":"في مثل هذا اليوم من سنة م تنيح القديس يوحنا الإنجيلي الرسول بن زبدي وأخو القديس يعقوب الكبير. ولد هذا القديس في بيت صيدا بالقرب من بحر الجليل وكان يعمل هو وأخوه مع والده زبدي في مهنة صيد السمك. وكانت عائلته غنية تمتلك بعض السفن تتلمذ أولا للقديس يوحنا المعمدان» ثم دعاه الرب يسوع هو وأخوه فتركا أباهما زبدي في السفينة مع الأجرى وذهبا \"؟. ويوحنا هذا هو التلميذ الذي كان يسوع يحبه؛ وهو الذي تبع السيد المسيح عند الصليب حتى سلم له القديسة مريم العذراء التي مكثت في بيته إلى يوم نياحتها '\". وهو أحد الثلاثة الأعمدة الذين خصهم الرب يسوع بمناسبات خاصة» فتجلى أمامهم على جبل طابور» واصطحبهم عند إقامة ابنة يايروس» وكانوا معه في بستان جثسيماني قبل القبض عليه. وهو كاتب إنجيل يوحنا الذي عن لاهوت السيد المسيح باستفاضة. كما كتب ثلاث رسائل تتحدث عن المحبة وكذلك سفر الرؤيا.\nكان القديس يوجنا أصغر التلاميذ سنا وعاش بتولا. وحضر حلول الروح القدس يوم الخمسين. بعد ذلك بر في أورشليم مع القديس بطرس» وحضر معه معجزة إقامة المقعد من بطن أمه عند باب الهيكل الجميل '\" والتي بسببها أمسكه اليهود هو وبطرس وقدموهما للمحاكمة أمام مجمع السنهدريم اليهودي \". .\nبعد نياحة القديسة العذراء مريم انطلق للتبشير في آسيا الصغرى وجعل مقر خدمته في أفسس. وهناك صنع الرب على يديه معجزة إقامة ابن وحيد لأمه من الموت فكانت سبا في انتشار الإبمان بالمسيح. كمابشر ي ميرنا © وأقام تلميذه القديس بوليكاربوس وبسبب خدمته الواسعة وإيمان الكثيرين بكرازته» قبض عليه الإمبراطور دومتيان وعذبه كثيرا حيث ألقاه في الزيت المغلي؛ ولكن الله أنقذه. ثم نفاه إلى جزيرة بطمس '\" فمكث فيها نحو سنة ونصف حيث رأى فيها رؤياه وكتب ما رآه في سفر الرؤيا. وبعد موت دومتيان عاد إل أفسس وتابع رعايته لكنائس أسيا الصغرى وأقام الأساقفة والكهنة. ولما تقدم في أيامه كانوا يجملونه إلى الكنيسة.\nالشعب واقتصر تعليمه على عبارة واحدة: \" يا أولادي أحبوا بعضكم بعضا \".\nهي أزمير بتركيا حاليا.\nدومتيان من سنة اباس الل جزيرة على شاطىء البحر الأبيض جنوب غرب تركيا. ومازالت في الخزيرة حق الآن معالم أثرية عن استقرار القديس يوحنا الرسول فيها.\nولما أحس القديس يوحنا بقرب نياحته خرج إلى خارج مدينة افسس وطلب من تلاميذه أن يحفروا له حفرة كبيرة ونزل فيها ورفع يديه وصلى واستودع روحه الطاهرة ق يدي الرب الذي أحبه 1 :\nفحزن عليه الشعب» ثم دفئوه ق الحفرة بإكرا م عظيم. | بركة صلواته فلتكن معنا.\nولربنا المجد دائما أبديا آمين."},{"d":5,"t":["استشهاد القديس أوساغنيوس الجندي","استشهاد القديس بانيكاروس","نياحة البابا ثيئودوسيوس الثاني البطريرك التاسع والسبعين من بطاركة الكرازة المرقسية","نياحة البابا متاؤس الأول البطريرك السابع والثمانين من بطاركة الكرازة المرقسية"],"b":"| في مثل هذا اليوم من سنة //ا للشهداء ( ) استشهد القديس - | 00 أوساغنيوس الجندي. كان هذا القديس من ضمن جنود الإمبراطور قسطنطين» وكان مسيحيا متدينا يتميز بالرحمة على الفقراء. ولما رأى قسطنطين علامة الصليب في السماء وتحتها عبارة \" بهذا تغلب \"؛ \" استدعى هذا الجندي الى واستفسر منه عن ذلك» فأجابه إنها علامة السيد المسيح \". وقد عاش هذا القديس حتى زمان الإمبراطور يوليانوس الجاحد. وذات يوم كان سائرا في أحد شوارع أنطاكية فوجد اثنين يتخاصمان وأوقفاه ليحكم بينهما نظرا لشيخوخته فحكم بينهما بالعدل وطيب خاطرهما . فوشى به رجل إلى الملك. فاستدعاه وانتهره قائلا: \" كيف تجعل نفسك حاكما \" أجابه القديس: \" أنا لست كذلك»؛ أما أنت فقد تركت عبادة الإله الحقيقي وسجدت للأوثان الشيطانية \" فغضب منه الملك وأمر بصلبه ووضع مشاعل في جنبيه»؛ فاحتمل بصبر وشكر.\n. وأخيرا أمر الإمبراطور بقطع رأسه. فنال إكليل الشهادة.\nبركة صلواته فلتكن معنا. آمين.\n\"--وفيه أيضا من سنة للشهداء (4 م ) استشهد القديس بانيكاروس الفارسي. كان هذا القديس من بلاد فارس. عمل في الجندية حتى وصل إلى قائد جند؛ وأحبه اللك لأجل تعرف على القديسين تادرس المشرقي ولاونديوس وصاروا أصدقاء. فلما سمع بهم الإمبراطور دقلديانوس منهم عن سبب هذه الصداقة؛ ثم أرسل بانيكاروس إلى أرمانيوس والي الإسكندرية والخمس مدن الغربية 6 مع أربعة من الجند 6 'وكان الوالي بإحدى الخمس مدن فأمر بطرحه في السجن. فظهر له السيد المسيح يشجعه ويقويه. وفي الغد أجلسوه على كرسي مملوء بالمسامير ووضعوا على رأسه خوذة حديد محماة وأوقدوا تحته النار. فأرسل الرب ملاكه وخلصه. بعد ذلك علقوه منكسا وربطوا حجرا في عنقه وأوقدوا المشاعل تحته؛ فخلصه ملاك الرب أيضا. وبعد سلسلة من العذابات التي كان الملاك يخلصه منهاء أمر الوالي بقطع رأسه فال إكليل الشهادة : فتقلام أحد إ لأمراء ويدعى وحمل جساده الطاهر إلى منزله وأخفاه حققى انتهي عصر الاضطهاد ثم بنى عليه كنيسة عظيمة.\nبركة صلواته فلتكن معنا. أمين.\nوفيه أيضا من سنة للشهداء ( 7 م تيح البابا يئودوسيوس الثاني البطريرك التاسع والسبعون من بطاركة الكرازة المرقسية. ولد القديس في مثية بنى خصيب '\"؛ وكان يسمى عبد المسيح بن أبى مكين. ترهب في دير أن فانا ل باسم الراهب ثيئودوسيوس. ولما خلا الكرسى البطريركلي بنياحة البابا يوأنس السابع » وقع اختيار الأساقفة على هذا فرسموه قسا في ديره ثم أتوا به إلى القاهرة ورسموه بطريركا سنة وقد هدأت في أيامه حركة الاضطهاد التى أثيرت على الأقباط في عهد سلفه.\nقام هذا البابا في سنة بتكريس الميرون المقدس في كنيسة القديس مرقوريوس أبى سيفين بمصر القديمة ومعه اثنا وأقام على الكرسي خمس سنوات وخمسة أشهر وثمانية وعشرين يوما ثم تنح بسلام ودفن بدير اللسطور بالبساتين \" بركة صلواته فلتكن معنا. أمين.\n؛ - وفيه أيضا من سنة 706 للشهداء ) تنح البابا القديس الأنبا متاؤس الأول البطريرك السابع والثمانون من بطاركة الكرازة المرقسية. ولد هذا القديس في بنى روح من )0 منية بق خصيب هي مدينة المنيا حاليا.\n\"© دير أبي فانا: مازالت آ آثار هذا الدير باقية في الصحراء غرب ملوي بمحافظة المنيا. وتم تعمير هذا الدير رهبانيا ومعماريا واعترف المجمع المقدس به كدير عامر بالرهبان بجلسته في 7 بشنس 19 مايو 4 :\nدير النسطور: مازاات تلا توجد منطقة بهذا الاسم بين المعادي ودار السلام بالقاهرة.\nأعمال الأشمونين ” '. رباه أبواه تربية مسيحية حقيقية ة وتعلم ق كتاب الكنيسة القراءة والكتابة. كما حفظ المزامير والمردات.\nوكان يرعى غنم أبيه. وقد مال إلى النسك والتقشف منذ صباء؛ ثم ترهب في دير أبو فانا ( آفا فيني ) القريب من بلدته وبعد عدة سنوات ذهب وأقام في دير القديسة العذراء الملعروف بالمحرق باسم الراهب متى» ولكثرة فضائله رسموه قسا. ذهب بعد ذلك إلى دير القديس أنطونيوس وكان يخدم شماسا و يعلم 0 أحدا أنه كاهن. وبينما هو ق الهميكل خرجت يد من المذبح البخور ثلاث دفعات, فعلم شيوخ الدير أنه كاهن وأنه : لابد أن يصير بطريركا. . هرب من الدير خوفا من المحد الباطل وذهب إلى أورشليم وعمل كأجير» وكان يقضى الليل ساهرا في الصلاة. ولما اشتهرت فضائله في أورشليم رجع إلى دير الأنبا أنطونيوس» وكان معاصرا للقديس مرقس الأنطوني؛ وقد ضيقات كثيرة من الأمير يبعا والي البلاد. وبعد أن تم إ لإفراج عنه ذهب إل دير المحرق وصار قدوة ومنشعة بعد انتقال البابا غبريال الرابع» اجتمع الأساقفة والأراخنة واستقر وأيهم على اختبار القس م لبصير بطريركا. فاختفي عندما مع الخبنء وبتدبير الله تم العشور عليه. ولما وصل مع الوفد إلى القاهرة وهو حزين » أخل مقصا وقص طرف لسانه,؛ حاليا قرية تابعة 2 ملوي ممحافظة المنيا.\nلكن الرب شفاه وأطلق لسانه. فتحقق لجع أنه المختار من الل فر موه بطريركا سنة 7/7 م.\nلما جلس على الكرسي لم يغير شيئا من نسكه واتضاعه وصلواته. واهتم بأديرة الرهبان والراهبات. كما كان محبا للفقراء مهتما بقضاء طلباتهم» ولم يبق شيئا من مال البطريركية» حتى خاصمه البعض واتهموه بالتبذير» ولكن به كثير من الأغنياء في عمل الرحمة.\nوكان البابا متاؤس عندما يقف على المذبح يلمع وجهه بنور سماوي ويرى السيد المسيح قائما. وقد وهبه الله موهبة شفاء كما كان حمامة سلام بين ملوك الحبشة والسلطان ملك مصرء الذي كانت تربطه به صداقة قوية. وقد حلت بهذا البابا. ضيقات كثيرة من خلفاء هذا السلطان.\nعرف البابا يوم نياحته وأصيب بحمى شديدة انتقل بعدها إلى السماء وله من العمر أكثر من سبعين عاما وقد جلس على الكرسى ثلاثين عاما وخمسة أشهر وستة ة أيام. ودفن بدير الخندق البطاركة أسفل كنيسة القديس الأنبا رويس بالقاهرة الأنطوني والقمص أبرآم الأنطوني.\nبركة صلوات الجميع فلتكن معنا.\nولربنا امجد دائما أبديا آمين.\nفي هذا اليوم تعيد الكنيسة بعيد ختان السيد المسيح له المجد؛ في"},{"d":6,"t":["عيد الختان المجيد","تذكار صعود إيليا النبي إلى السماء حبا","استشهاد الأربعة أراخنة بإسنا. |","نياحة البابا مركيانوس البطريرك الثامن من بطاركة الكرازة المرقسية","نياحة البابا غبريال الثالث البطريرك السابع والسبعين من بطاركة الكرازة المرقسية","نياحة القديس باسيليوس الكبير رئيس أساقفة قيصرية الكبادوك","تكريس كنيسة الشهيد إسحاق الدفراوي"],"b":"ه - نياحة البابا مرقس البطريرك الثالث والسبعين من بطاركة الكرازة المرقسية.\nومو ووو اليوم الثامن من ميلاده حسب الناموس اليهودي» لكي يكمل كما يقول مغلمنا القديس بولس الرسول: \" وأقول أن يسوع المسيح قد صار خادم الختان من أجل صدق الله حتى يثبت مواعيد الآباء \" \". ثم أعطانا علامة العهد الجديد بالمعمودية كما قال معلمنا القليس بولس الرسول \" وبه أيضا غير مصنوع بيد» بخلع جسم خطايا البشرية» بختان » مدفونين معه في المعمؤدية 6 التي فيها أقمتم أيضا معه يمان عمل \"الله الذي أقامه من الأموات. وإذ كئتم أمواتا في .\nوخلف جحسدكم بكم بم مماعائل ب ون_ت» رومية 119 م.\nاليوم السادس من شهر طوبه المبارك , اليوم السادس من شهر طوبه المبارك ''\". أي أننا في عهد النعمة نحفظ الختان الروحي القلي 0 وقد كانوا من رؤساء إسنا وكتابها والمشرفين على أمورهاء بالتوبة عن الخطايا لنحيا للرب في البر والقداسة.. ا وكانوا يعطون الفقراء والمساكين ويعولون الأرامل والأيتام؛ الختان هو أحد الأعياد السيدية السبعة الصغرى التي فوقفوا أمام الوالي معترفين بإيمانهم بالسيد المسيح غير مبالين تعيد فيها الكئيسة للسيد المسيح له المجد إل الأبد أمين. : بالتهديد والتعذيب » فأمر الول ب\" بتعذييهم عذابا وحشا فلم \" - وقد رثبت الكنيسة أن يكون هذا اليوم تذكارا لصعود إيليا الني | يتزعزعوا عن إيمانم. . أخيرا أمر الوالي بقطع رؤوسهم فنالوا إلى السماء حياء وذلك أنه لما علم إيليا بأمر صعوده ذهب مع | أكاليل الشهادة.\nتلميذه اليشع من الجلجال إلى بيت إيل حيث أعلم تلميذه البشع ل 0 بركة صلواتهم فلتكن معنا آمين. 0 ثم ذهبا سويا إلى نهر الأردن وضرب إيليا مياه النهر 0 | 4 < وفيه أيضا من سبنة تنيح الأب القديس مركيانوس المياه إلى نصفين فعبر كلاهما على اليابسة. وبينما ]| البطريرك الثامن من بطاركة الكرسي المرقسي. ولد هذا القديس هما يسيران ويتكلمان إذا مركبة من نار وخيل من نار ففصلت بالإسكندرية وتعلم بهاء ولكثرة علمه جعلوه مديرا لمدرسة بينهما فصعد إيليا في العاصفة إلى السماء» وكان اليشع تلميذه | الإسكندرية اللاهوتية. وقد اشتهر بالفضيلة؛ فلما خلا يرى وهو يصرخ يا أبى يا أبى» يا مركبة إسرائيل وفرساناء وم 8 الكرسي المرقسي بنياحة الأنبا ميو » التخبوه بطريركا سنة .\nورفع أليشع الني رداء إيليا الذي سقط عنه ووقف - | م فحقق آمال ناخبيه حيث اهتم بتعليم الشعب وحثهم على شاطىء : نهر الأرذن وضرب به لماه فانفلق إلى نصفين | . على المشابرة أمام الاضطهاد الوثني وبعد أن أقام على الكرسي ومشى على اليابسة راجعا إلى حيث كان ” ض 1 عشر سنوات وشهرين تنيح بسلا ودفن بالكنيسة المرقسية ' بركة إيليا الني وتلميذه اليشع فلتكن م معنا. آمين. بالإسكندرية. ض - وفيه أيضا من سنة 9 للشهداء ( )' استشهد الأربحة ] | بركة صلواته فلتكن معنا. آمين.\nأراخنة بإسناء ففي عودة الوالي إريانوس إلى إسنا للمرة الثانية م 90 - وفيه أيضا من سنة 406 للشهداء ( ) تنيح البابا قابله الأآربعة أراخنة أوسافيوس وسامان وهرواج وباخوش؛ | القديس مرقس الثالث البطريرك الثالث والسبعون من بطاركة المرقسية. كان |سبمه الشماس أبو الفرج بن أ السعد» وهو من أصل سرياني ويعمل بالتجارة. واشتهر بالطهارة وا/ا» 17 - :7 كولوسى والنسك. واختير بطريركا في سنة 1765 م؛ فلما جلس على الكرسي المرقسي خدم شعبه بكل طهارة وصلاة ودموع كثيرة بسبب الضيقات التي حدثت أثاء الحروب ولما تولى صلاح الدين الأيوبي مقاليد الحكم بمصرء أحوال الأقباط. فقام قداسته بجولة رعوية افتقد فيها شعبه في كل أنحاء مصر وبعد أن جلس على السدة المرقسية وعشرين عاما وسبعة أشهر تنيح بسلام وذفن بدير_.\nالقديس مكاريوس ببرية شيهيت.\nبركة صلواته فلتكن معنا. آمين.\n- وفيه أيضا من سنة /4/8 للشهداء ) تنح البابا غبريال \" الثالث البطريرك السابع والسبعون من بطاركة الكرازة المرقسية» وقد قام بعمل الميرون الملقدس في كنيسة العذراء - المعلقة - بمصر القديمة» واشترك معه الأساقفة» وذلك خلال فترة حبريته التي لم تتجاوز السنتين» ثم تنيح بسلام ودفن بكنيسة الشهيد مرقوريوس أبى سيفين بمصر القديمة.\nبركة صلواته فلتكن معنا. آمين.\n- وفيه أيضا من سنة 40 للشهداء ) تنح القديس العظيم باسيليوس الكبير رئيس أساقفة قيصرية الكبادوك. ولد سنة 4 في سبسطية بالكبادوك من أسرة متدينة وكان له أخوان هما غريغوريوس أسقف نيصص وبطرس أسقف سبسطية. تعلم العلوم الفلسفية والطبيعية وعلم الخطابة في قيصرية فلسطين ثم في القسطنطينية وأثينا» وكان صديقا وزميل دراسة للقديس غريغوريوس الناطق بالإلهيات ( الثيثولوغوس ) ويوليانوس الذي صار بعد ذلك إمبراطورا وجحد الإبمان بالسيد المسيح.\nذهب لتلقى العلم أيضا ق أنطاكية عند الفيلسوف ليبانيوس الأنطاكي واشتغل زمانا بمهلة المحاماةي وف سنة 07 آم هجر العالم وجاء إلى مصر وطاف ق براريها يتعلم من رهبانها التقوى والفضيلة وحياة السك ثم عاد واعتزل ق بريه ة بنطس ومارس حياة النسك والعبادة. فلما شاع حبر قداسته التف حوله كثيرون فأقام لم ديرا ووضع م القوانين اللازمة لإرشادهم في طريق الكمال الإنجيلي» وهكذا صار هو المؤسس الأول للرهبنة في بلاد البنطس والكبادوك.\nوف سنة نال درجة الكهدوت»؛ وأخذ يعلم المؤمنين الضالين ونظرا لقداسة سيرته وسبمو علمه وفضيلته؛ اختاروه رئيسا لأساقفة الكبادوك سنة لآم. فلاقى متاعب كثيرة من الإمبراطور فالنس الأريوسي احتملها بشكرء وقد أجرى الرب على يديه العديد من العجائب والمعجزات»؛ وهو الذي كتب القداس الباسيلي» الذي تستعمله كنيستنا القبطية.\nكما وضع العديد من الكتب الروحية والتفسيرية والنسكية والقوانين الكنسية. ولما أكمل سعيه الصالح تنيح بسلام.\nبركة صلواته فلتكن معنا. امين.\n4 - وفيه أيضا تذكار تكريس كنيسة القديس إسحاق الدفراوي الشهيد» فبعد استشهاده ''؟ أخذ المؤمنون جسده الطاهر في وأرسلوه إلى بلدته دفرة 00 حيث بليت له كنيسة في نفس المكان الذي كان يعيش فيه وكرسها أسقف الإيبارشية في مثل هذا اليوم؛ ووضع فيها الجسد الطاهر. وقد أظهر الرب عجائب كثيرة في هذه الكنيسة فكان كل الذين أصابتهم أمراض إليها وينالون الشفاء بمجرد دخولم فيها من جسد القديس.\nبركة صلوات هذا الشهيد الطاهر فلتكن معنا.\nولربنا المجد دائما أيديا أمين.\n)0 تعيد 1 كي 7 بتاريخ أ\" شهاد القديس إسحاق الدفراوي ق ل\" بشنس.\n)\"0 دفرة: قرية مازالت بنفس احمها تابعة لمركز طنطا بمحافظة الغربية."},{"d":7,"t":["نياحة القديس سلفستروس بابا روما"],"b":"في مثل هذا اليوم من سنة 0 للشهداء ( \"م ) تنيح القديس سلفستروس بايا روما. ولد هذا القديس ق روما من أبوين مسيحيين وبعد وفاة والده ربته أمه على المبادىء المسيحية وتثقف بالعلوم الدينية والفلسفية 6 فر#بموه كاها. ولما ظهرت فضائله اختاروه بطريركا بعد انتقال البابا ملطيانوس مسنة في أيام المللك قسطنطين الكبير..\nوقام أيضا هذا البابا بإصلاح ما أفسده المضطهدون» واهتم بتعليم الشعب وتثبيته على الإيمان المستقيم» كما عقد مجمعا في فرنسا حرم بدعة الدوناتيين.\nوفي أيام هذا البابا انعقد المجمع المسكوني الأول في مدينة نيقية سنة لمحاكمة أريوس الذي حضره \"8 أسقفا. وحكموا فيه بحرم السيد المسيح ووضعوا في هذا المجمع أيضا قانون الإيمان النيقاوي.\nولما أكمل سعيه الصالح تنيح بسلام بعد أن قضى على الكرسي إحدى عشرة سنة. . ') بركة صلواته فلتكن معنا.\nولربنا المجد دائما أبديا آمين.\nدياف"},{"d":8,"t":["عودة رأس القديس مار مرقس الرسول","نياحة البابا أندرونيقوس البطريرك السابع والثلاثين من بطاركة الكرازة المرقسية","نياحة البابا بنيامين الأول البطريرك الثامن والثلاثين من بطاركة الكرازة المرقسية","نياحة البابا غبريال الخامس البطريرك الثامن والثمانين من بطاركة الكرازة المرقسية"],"b":".. تذكار تكريس كنيسة القديس مكاريوس الكبير - - في مثل هذا اليوم من سنة 318 للشهداء تيد الكئيسة بتذكار عودة رأس القديس مار مرقس الرسول. كانت الرأس المقدسة محفوظة في كنيسة بوكاليا أو دار البقرء فدخل أحد البحارة العرب فوجد تابوتا توهم أن به ذهبا ولما وضع يده داخل التابوت أمسك بالرأس وأخذها ليلا وأخفاها في السفيئة.\nولما عزم القائد عمرو بن العاص على المسير أبحرت كل السفن ما عدا تلك السفينة التي بها الرأس فأمر القائد بتفتيش السفينة فوجدوا الرأس مخنبأة فيها فأخرجوها من السفينة بعذها تحركت استدعى القائد البحار فاعترف بجريمته فعاقبه. ثم سأل عمرو عن بابا الأقباط وهو الأنبا بنيامين الثامن والثلاثون وكان بأديرة الصعيد فأرسل له خطاب أمان وطلب منه فحضر البابا واستلم منه الرأس المقدس.\nبركة القديس مار مرقس الرسول فلتكن معنا أمين.\n7- وفيه أيضا من سنة 74 للشهداء ( ) تنيح البابا أندرونيقوس البطريرك السابع والثلاثون من بطاركة الكرازة المرقسية. ولد هذا الأب بالإسكندرية من أبوين مسيحيين غنيين.\nودرس الكتب المقدسة ونظرا لعلمه وتقواه رسموه شماساء فاهتم بخدمة الفقراء والمساكين وبعد نياحة البابا أنسطاسيوس اتفق الآباء الأساقفة والأراخنة على رسامته بطريركا وتمت رسامته يوم ؛؟ كيهك 777 للشهداء ). وقد نال هذا الأب شدائد من الفرس المستعمرين إذ خربوا ستمائة دير عامر بالرهبان حول الإسكندرية وقتلوا من فيها من الرهبان» كما قتلوا سبعمائة راهب كانوا في مغائر حول هذه الأديرة. أما البابا القديس فكان يتنقل بين شعبه ليواسيه ويثبته على الإيمان والصبر. وبعد أن أكمل جهاده الحسن تنح بسلام.\n: بركة صلواته فلتكن معنا. أمين.\n“- وفيه أيضا من سنة /717 للشهداء تنيح البابا بنبامين الأول البطريرك الثامن والثلاثون من بطاركة الكرازة المرقسية.\nولد هذا الأب ببلدة بيرشوط '\" من أبوين مسيحيين غنيين تربية مسيحية ولما كبر ترهب عند ناسك قديس يدعى ثاؤنا بدير القديس قبريوس غري الإسكندرية فنما في الفضيلة ودراسة الكتب المقدسة. ورأى في رؤيا ملاكا يخيره أنه سيرعى السيد المسيح فأعلم أباه الروحي بالرؤيا فنصحه وحذره ''؟ بيرشوط: هي بلدة كفر مساعد التابعة لإيتاى البارود بمحافظة البحيرة.\nمن الكبرياء ومن حرب العدو الشيطان وازداد في النسك والصلاة. ولظروف معينة اضطر الناسك القديس ثاؤنا أن ينتزل إل الإسكندرية فأخذ معه تلميذه بنيامين وهناك ذهبا ليتباركا من البابا حيث روى له ما رآه بنيامين فأعجب به البابا واستبقاه معه ليساعده في العمل الرعوي.\nولما تنيح البابا أندرونيقوس اختاروا القس بنيامين بالإجماع بطريركا ورسم يوم 4 طوبه سنة 74 للشهداء ( ).\nنال هذا الأب شدائد كثيرة من المقوقس» الوالي والبطريرك الخلقيدوني في نفس الوقت» وبإرشاد إلهي هرب البابا إلى برية شيهيت ورأى بنفسه ما حل بالبرية من خراب على أيدي الفرس. ثم انطلق من شيهيت إلى الصعيد حيث عاش في أحد الأديرة وكتب من هناك رسائل باباوية يثبت فيها الشعب على الإيمان واحتمال الآلام وظل هناك ثلاث عشرة سنة.\nعاد البابا بنيامين إلى مقر كرسيه بعد أن وصلته رسالة أمان من عمرو بن العاص واستلم منه أيضا رأس القديس مار مرقس الرسول التي كان قد سرقها أحد البحارة.\nواهتم البابا بافتقاد شعبه وتعمير الأديرة والكنائس التي ولما كانت الكنيسة المليئضة الخلقيدونية قد أدخلت بعض التعاليم الغريبة في الأرثوذكسية» اهتم هذا البابا بتوضيح العقيدة السليمة فرجع الكثيرون إلى حضن الكنيسة وأعلنوا توبتهم فقبلهم. واهتم أيضا بالرعاية فرسم أساقفة وكهنة. وأراد الله أن يريحه من أتعاب هذا العالم فتنح بسلام. ..\nبركة صلواته فلتكن معنا. آمين.\n4 - وفيه أيضا من سنة 147 للشهداء ( ) تنح البابا غبريال الخامس البطريرك الثامن والثمانون من بطاركة الكرازة المرقسية. كان هذا الآب من رهبان دير القديس العظيم الأنبا صموئيل المعترف وسار في حياة الرهبئة بسيرة فاضلة حتى لقبه إخوته الرهبان باسم غبريال الأمجد وفاحت سيرته العطرة لذلك عنه سلفه البابا متاؤس الأول أنه سيصير بطريركا بعده؛ وحينما اجتمع الأساقفة والأراخنة لاختيار بابا الإسكندرية هذه النبوة فرسموه بطريركا في 7 برموده سنة \" للشهداء ). اشتهر هذا البابا بالبساطة والتقشف فكان يفتقد شعبه 7\" على الأقدام. وقد نالته شدائد كثيرة فبذل كبيرا في تثبيت الشعب على الإيمان واهتم بعمارة الكنائس التي تهلمت.\nوكان هذا البابا رسول سلام بين سلطان مصر وملوك الحبشة. واهتم بالطقوس الكنسية ووضع لها كتابا. ولما أكمل جهاده الصالح تنبح بسلام ودفن بإكرام في كنيسة القديسة العذراء ببابلون الدرج بمصر القديمة.\nبركة صلواته فلتكن معنا. آمين.\nالضف لال 1 ض اليوم الثامن من شهر طوبه المبارك | اليوم التاسع من شهر طوبه المبارك ال - وفيه أيضا من سنة 77 للشهداء ( ) تم تكريس كنيسة إ اليوم التاسع من شهر طوبه المبارك) القديس مكاريوس الكبير بديره ببرية شيهيت على يذ الثابا الأول البطريرك الثامن والثلاثين. وأثناء تكريس المذبح - نياحة القديس أبرآم رفيق الأنبا جاورجي.\n- نياحة القديس أنبا فيس.\nشاهد شيخا منيرا فقال ف نفسه إن هذا الراهب يصلح \" فأتاه ملاك الرب وقال له: \" هل تجعل هذا الشيخ أسقفا وهو القديس مكاريوس أب البطاركة والأساقفة والرهبان وقد حضم اليوم ليفرح مع أولاده \" فإن حفظ الرهبان وصاياه في المجد. وإن خالفوا فليس ليم معه فأجاب القديس مكاريوس الملاك قائلا \" العنقود إذا بقيت فيه حبة واحدة فإن بركة الرب تكون فيه لأنه إذا بقيت المحبة فأنا أؤمن أن الرب لا يبعدهم عن ملكوته \" فتعجب البابا بنيامين من رحممه القديس مكاريوس.\nولربنا المجد دائما أبديا آمين.\nليف - في مثل هذا اليوم من سنة 504 للشهداء ( ) تنيح القديس الناسك الأنبا أبرام رفيق الأنبا جاورجي. ولد هذا القديس من أبوين مسيحيين تقيين وربياه على البر والتقوى وعمل الخير لجميع الناس ومات والده وهو صغير. ولما كبر اشتاق إلى حياة الرهبنة؛ أمه هذه الرغبة وصلت إلى الله لكي يقبل تكريسه ورفعت يديها إلى السماء وقالت: \" يارب اقبل منى هذا القربان \".\nفذهب إلى دير القديس مكاريوس ببرية شيهيت؛ وتتلمذ للقديس الأنبا يوأنس قمص البرية. وكان يجتهد في الصلاة والصوم والنسك والوحدة حتى وصل إلى مرتبة عالية من القداسة.\nوبتدبير من الله تعرف على القديس جاورجى وصارا وعاشا معا في قلاية بيجيج بالقرب من دير القديس مكاريوس إلى نياحة الأنبا يوأنس قمص شيهيت.\nالأنبا أبرام مرضا شبديدا دام 18 سنةء احتملها بصبر ولما دنت ساعة انتقاله تناول من الأسرار المقدسة. وجاء فاستودع روحه الطاهرة في يد الرب الذي أحبه.\nبركة صلواته فلتكن معنا. آمين.\nالي"},{"d":9,"t":[],"b":"وفيه أيضا تنيح القديس أبا فيس. كان من أهل أدنا التابعة \"\". رباه والداه تربية مسيحية وبعد نياحتهما عبر النيل إلى ناحية الشرق وجاء إلى القديس أباهور بجبل العمود ( جبل سوادة شرق المنيا ) \". فاستقبله القديس أباهور فرحا وألبسه إسكيم الرهبنة» فأجهد أبا فيس نفسه بنسكيات كثيرة بلا ملل حتى دعوه الصبور. وبعد نياحة أبيه الروحي أبا هورء قام وعبر النهر إلى ناحية الغرب وانفرد في العبادة في مكان على الشاطىء الغربي للنيل. وفي ذات يوم ظهر له السيد المسيح وأعطاه السلام ثم حدد له أساس كنيسة ومكان مجمع للرهبان ب وأمره أن يبدا بالبناء. فاجتمع حوله حوالي مائة أخ وبنوا مجمع».\nالرهبان والكنئيسة؛ وكان أبا فيس أبا روحبا لهم. وقد احتمل حروبا كثيرة من الشيطان وكان ينتصر عليه بقوة الله. وفي أواخر حياته انفرد هو وأحد تلاميذه في مكان يدعى جبل الملح وهناك أكمل جهاده الصالح وتنيح بسلام» فأخذ تلميذة الجسد الطاهر وأتى به إلى مجمع الرهبان حيث دفنوه بإكرام عظيم. وقد ظهرت عجائب وأشفية كثيرة من جسده الطاهر. وكانت هذه المنطقة دعى قديما مني بنى خصيب ثم صارت تدعى مثية أبو فيس؛ وقد حلت محلها مدينة المنيا حاليا.\nبركة صلوات القديس أبا فيس فلتكن معنا. ولربنا المجد دائما أبديا آمين.\n'\"\" الأشمونين: حاليا قرية تابعة لمركز ملوى بمحافظة المنيا. | :\nجبل سوادة: نسبة لقبيلة عرب سوادة الي أقامت فيها فترة من الزمان سمي الحبل باسمها.\nجوتت بجعي عبوبةتنتسيسسسسب يسم"},{"d":10,"t":["نياحة القديس يسطس تلميذ الأنبا صموئيل المعترف"],"b":"- برمون عيد الغطاس المحيد.\nالكنيسة المقدسة أن يكون هذا اليوم برمون لعيد الغطاس الطقسية أن يكون البرمون يوما أما إذا وقع العيد يوم الاثنين» فيكون البرمون ثلاثة أياء أولما يوم الجمعة ويصام انقطاعيا للغروب : ثم يومي السبت والأحد يصامان صوما عاديا إذ لا يجوز فيهما الصوم الانقطاعى. \"م وإذا وقع العيد يوم الأحد فيكون البرمون يومين» الجمعة صوما عاديا. وقرأ فصول يوم طوبه في كل أيام البرمون. ض نسأل إلهنا الصالح أن يقبل أصوامنا ويطهرنا من خطايان أهلا لإظهار مجده بأعمالنا كما أظهره على نهر الأردن.\nله امجد الدائم إل الأبد آمين.\n- وفيه أيضا تنيح القديس يسطس تلميذ القديلس الأنبا صموئيل المعترف. ولد في أنطاكية وكانت له أخت عذراء اسمها مدرونة.\nولما بلغ سطس العشرين من عمره اشتاق إلى حياه الرهينةء أنه على عزمه؛ فأصرت على الذهاب معه» وحلقت شعر رأسها وتزبت بز الرجال» ثم خرجا معا من قصرهاء على أقدامهما مدة يومين حت تعباء فوجدهما شيخ راعى على هذا الإعياء » فاقتادها إلى كوخه ليسترمجا : ثم أرسل معهما صبيا أرشدهما إلى شاطىء البحر. وهناك وجدا سفينتين بهما بعض القراصنة» ففتشوهما ليأخذوا ما معهماء ولما لم يجدوا شيا أخذت كل سفيئة واحداأ منهما وهكذا افترقا عن وعندما وضصلوا بال شاب 0 5 س إلى الشواطىء المصرية 7 من أكابر مريوط أسبمه أرشليدس فمكث يسطس ف بيته يخدم بأمانة مدة خمس سنوات ونال نعمة ق أعين الجميع. إلا أنه ق أحد الأيام حقد عليه زملاؤه العيد وضربوه ء ضربا مبرحا حى ل سبعة ة أيام طرييحا لا يستطيع الحركة 6 ولما قام وهرب من منزل سيده وأقام منفردا ق كر خا رج مد ينه مر يوط.\nإلهي 6 مرض الأرخن د أرشليدس 1 فذهب إلى برية شيهيت ليتبارك من الرهبان ويطلب صلواتهم لشفائه » وهناك التقى بالأنبا صموئيل» » فصلى له وأمره أن يرجع إلى بلده عودته سيقابل رجلا معه جره ة ماء يشرب منها فيشففى من مرضه 6 وفعلا ركب الأرخن دانته ليعود إلى بيه 6 وبالقرب من رأى رجلا حاملا جره ة ماء 6 فشرب منها وشفي 6 ولم على ذلك الرجل حامل الحرة حيث كان هو عبده ثم ذهب يسطس إلى طبيب يدعى قلتة وسكن عنده ممس سنوات مرضت في أثنائها زوجة الأرخن أرشليدس» فأرسل الطبيب قلتة. فظهر ملاك الرب للطبيب وأخبره بأن على يد خادمه يسطس» فأخذه م معه عه رغما عنه إلى وهناك صلى القديس يسطس على ماء وشربته فشفيت الجميع شاكرين الله فرحين مبتهجين ذه ومكث القديس يسطس ق بيت أرشليدس نحو ستة أشهر وتبارك منه الجميع.\nثم انطلق القديس يسطس إلى برية شيهيت وتتلمذ على يدي القديس الأنبا صموئيل المعترف» عاكفا على النسك والصوم والصلوات عدة سنوات» وبعد ذلك انفرد متوحدا في مغارة هجم البزبر على الدير وأخذوه معهم وباعوه بالبهنسا.\n8 قام فيها صابرا محتملا التجارب ف صمت وشكر لله . وظهر ملاك الرب للقديس الأنبا صموئيل وأعلمه بمكان تلميذه يسطس ففرح وذهب إليه وشجعه وعزاه وقواه ثم عاد إلى ديره.\nوبعد قليل أكمل القديس يسطس جهاده الصاح وتنيح بسلام .\nبركة صلواته فلتكن معنا.\nالمجد دائما أبديا آمين.\nتايف"},{"d":11,"t":["عيد الظهور الإلهي ( الغطاس المجيد","نياحة البابا يوأنس السادس البطريرك الرابع والسبعين من بطاركة الكرازة المرقسية"],"b":"نياحة البابا بنيامين الثاني البطريرك الثاني والثمانين من بطاركة الكرازة المرقسية. - جوذ؛هجههن - تحتفل الكنيسة اليوم بعيد الغطاس المجيد؛ ويسمى باللغة اليونانية عيد الثيئوفانيا أي الظهور الإلمي. ففي مثل هذا اليوم من سنة 7 ميلادية اعتمد السيد د المسيح له امجد من يد القديس يوحنا المعمدان في نهر الأردن \"» فظهر الثالوث القدوس للجميع الآب ق السماء يقول \" هذا هو أبني الحبيب الذي به سررت” والابن في مهر الآردن والروح القدس نازلا عليه مثل حمامة. كذلك ظهر أيضا جد السيد المسيح لأنه 1 يظهر نفسه في مدة الثلاثين سنة الماضية» فأظهر ذاته في مثل هذا اليوم لبنى إسرائيل \".\nوقد أسس السيد المسيح بعماده سر المعمودية المقدس أول الأسرار وباب الدخول إلى ملكوت الله. فكل من آمن واعتمد :0 حينما يحفظ عهد معموديته بالتوبة الدائمة الله الذي تنازل وصار في الهيئة مت ار : » ورسم لنا طريق الحياة الأبدية. له المجد الدائم إلى \" - وفيه أيضا من سئة 977 للشهداء ( ) تنح البابا يوأنس السادس» البطريرك الرابع والسبعون من بطاركة الكرازة المرقسية. كان اسمه أبو المجدء ويعمل بالتجارة. وكان شماسا تقيا علوم الكنئيسة » ذا وجه بشوش وحديث عذب.\nولما خلا الكرسي البطريركي بنياحة البابا مرقس الثالث» اتفق رأى الجميع على اختيار هذا الشماس لرتبة البطريركية فلما جلس على الكرسي المرقسي» اهتم برعيته في مصر والحبشة.\nوكان صديقا للسلطان صلاح الدين الأيوبي وعالج كل المشاكل بالحكمة والعلاقات الطية مع الجميع. وفي أيامه بطل إرسال الأساقفة إلى الخمس مدن الغربية. ولما أكمل سعيه بسلام» انتقل إلى الفردوس بعد أن جلس على الكرسى ي المرفسي حوالي 77 بركة صلواته فلتكن معنا. آمين.\n- للشهد أ ) أاكرؤرل م 4 تيح الأ 0 وفيه أ يضا من نسنة القديس الأنبا بنيامين الثاني البطريرك الثاني والثمانون من بطاركة الكرازة «المرقسية. كان من أهال الدمقراط التابعة بمحافظة قنا. وصار راهبا يجبل طره باسم بنيامين. وتنبأ له القديس. برسوم العريان أنه سيصير بطريركا. فلم خلت السدة المرقسية بنياحة البابا يوأ نس التاسع اجتمع الآباء للا الأساقفة والكهنة والأراخنة ووقع اختيارهم على الراهب سنة باسم البابا بنيامين الثاني. فاهتم به عمرانيا ورهبانيا. كما قام بعمل الميرون ق دير القديس مكاريوس سنة واشترك معه عشرون أسقفا. وحدث في عهده اضطهاد للأقباط على يد والي مصر شرف الدين بن ملك الحبشة للصلح وهد الموقف» وأعاد الأقباط بناء الكنائس التى تهامت.\nوبعد جهاد طويل في خدمة الكنيسة نحو اثنتي عشرة سنة تنيح بركة صلواته فلتكن معنا.\nولربنا المجد دائما أبديا آمين.\nبتعمير الكدائس والأديرة وخاصة دير الأنبا بيشوي الذي اهتم | بسلام ودفن في دير القديس العظيم الأنبا بيشوي ببرية شيهيت."},{"d":12,"t":["تذكار رئيس الملائكة الجليل ميخائيل","استشهاد القديس تادرس المشرقي","استشهاد القديس أناطوليوس"],"b":"| ثاني أيام عيد الغطاس المجيد. - ووو ووو - ربت الكنيسة أن يكون هذا اليوم ثاني أيام عيد الغطاس المجيد وقام الصلاة فيه بالطقس الفرايجي ولا يصام انقطاعيا.\nبركة مخلصنا الصاح الذي اعتمد لأجلنا فلتشملنا جميعا آمين.\nالجليل ميخائيل رئيس جند الرب الشفيع في جنس البشر.\nشفاعته المقدسة فلتكن معنا. أمين.\nوفيه أيضا من سنة ؟؟ للشهداء ( ) استشهد القديس تادرس المشرقي. ولد هذا القديس سنة في مدينة صور لذلك ييدعى بالمشرقي تمييزا له عن القديس تادرس كان والده وزيرا أما هو فكان قائدا للجيش الروماني؛ ضد الفرس. ورأى في رؤيا سلما مرتفعا إلى السماء وعند جلس الزب يسوع المسيح ومعه ملائكته وأسفل السلم رأى الذي هنو الشيطان» وقد أبلغه الوب أنه سيسفك دمه مع لاا \"0 اليوم الثاني عشر من شهر طوبه المبارك اليوم الثاني عشر من شهر طوبه المبارك سلمه للوالي ليحاكمه ويعذبه ثم أمر بنفيه حيث ظلوا يعذبونه \"0 حدث صلح مع الفرس فرجع القديس إلى أنطاكية ووجد أن | ولما عجر رومانوس أعاده إلى الملك الذي أمر بتعذيه دقلديانوس كفر بالإيمان وطلب منه أن يبخر للأوثان فرفض بالضرب والجلد والعصر بالحنبازين وقطعوا لسانه ثم ألقوه , | وأعلن إمانه بالسيد المسيح وصاح في جنوده قائلا: \" من أراد | للوحوش وكان الرب يرسل ملاكه ليشفيه ويقويه ولما ضاقوا 0 الاستشهاد على اسم السيد المسيح فليأت معي \" فصاحوا من تعذيبه قطعوا رأسه بحد السيف فنال إكليل الشهادة.\n0 جميعا: \" نحن معك وإلهك هو الحهنا \". , ض ض ض 1 فاغتاظ الإمبراطور وأمر الجنود أن يسمروه على شجرة وأن | ض بركة صلواته فلتكن معنا.\nفي عذابه ولكن الرب كان يقويه ويعزيه. بعد ذلك ن ولربنا المجد دائما أبديا أمين.\nوكان رئيس الملائكة ابل يأ إليه لميشجعه : أخيرا أحرقوه | : حيا ق أيام حكم مكسيميا يائوس وجالريوس فال إكليل \" | الشهادة.\nبركة صلواته فلتكن معنا. آمين.\nا\" 4 - وفيه أيضا من سنة للشهداء ( 4 م ) استشهد القديس أناطوليوس الفارسي» ولد هذا القديس في بلاد فارس والتحق \"| بالجيش الروماني وارتقى إلى رتبة قائد وظل فيه خمسة عشر عاما.\nلما كشر دقلديانوس وأثار الاضطهاد على المسيحيين اشتاق \"0 هذا القديس إلى الإكليل السماوي أفضل من مجد هذا العالم \"0 الرائل فأتى وخلع ثياب الجندية أمام الإمبراطور وأعلن إيمانه |\" بالسيد المسيح دهش الملك من جرأته » وإذ علم أنه من الفرس #“\" لاطفه ثم سلمه إلى الوالي رومانس لعله يتراجع عن إيمانه.\n43 ض | ض ض 3"},{"d":13,"t":["عيد عرس قانا الجليل","استشهاد القديسة دميانة"],"b":"1 نياحة القديس اؤفيلس الراهب.\n- تحتفل الكنيسة اليوم» بأحد الأعياد السيدية السبعة الصغرىء وهو عيد عرس قانا الجليل» الذي كت فيه الآية الأول التي صنعها الرب يسوع المسيح وأظهر ا مجده وقدرته على كل وبسببها امن به تلاميذه 0 وانفتح للآخرين باب الإيمان» وذلك أن الرب قا بتحويل الماء إلى خمر. وبحضوره في بارك سر الزواج الذي رسمه في كنيسته وجعله سر كما تأيد ذلك فيما بعد من قول معلمنا القديس بولس الرسول عنه \" هذا السر عظيم \" ”\". وما جعه الله لا يفرقه الإنسان ” ض ورغم أن السيد المسيح قام بتحويل الماء إل خمر في عرس قانا الجليل - حسب عوائد اليهود - إلا أنه يحذرنا من السكر بقوله أنه يعاب من يأكل ويشرب مع السكارى 5 وحذرنا معلمنا القديس بولس الرسول من السكر بالخمر بقوله: \" لا تسكروا | أف م بركة الذي فيه الخلاعة \" \"'\". ونهانا عن مخالطة السكارى بقوله \" لمن الويل» لمن الشقاوة... للذين يدمنون الخمر \" .\nربنا يسوع المسيح الحالة في عرس قانا الجليل تحل علينا وعلى بيوتنا بركة روحية. أمين. | وفيه أيضا من سنة للشهداء (4 م ) استشهدت أميرة القديسة دميانة العفيفة؛ ابنة مرقس والي البرلس والزعشران ووادي السيسبان. ولدت دميانة في أواخر القرن الثالث الميلادي فرباها أبواها تربية مسيحية حقيقية. فلما كبرت عزمت أن تعيش حياة البتولية فوافقها والدها على | دميانة يوما ما أن الملك دقلديانوس ذلك» وبنى لها قصرا لتعيش فيه مع أربعين عذراء كن يقضين في الصوم والصلاة وقراءة الكتب المقدسة. وسمعت والدها على التبخير للأوثان» فحزرنت كثيرا ثم صلت هي والعذارى من أجل ؛ والدها وقامت وذهبت إليه وعاتبته قائلة \" ككت أود أن أ ممع خبر انتقالك إلى الفردوس من أن أسمع أنك قد تركت إبمانك \".\nفندم أبوها وقام وذهب إلى الإمبراطور واعترف أمامه بالسيد المسيح. فحاول الإمبراطور بالملاطفة أن يثنيه عن إمانه بسبب :6 اكو © أم ويح محبته له» ولكنه رفض فأمر بقطع رأسه ونال إكليل الشهادة؛ ولما علم الملك بأن دميانة ابنة مرقس هي السبب في ذلك أرسل إليها قائدا ومعه مائة جندي لكي يجبرها على إتكار إعانهاء متمسكة بإيمامها. فعذمها كثير بكل أنواع العذاب وكان الرب يقويها ويقيمها سالمة. أخيرا قطع رأسها مع الأربعين واستشهد معهن أربعماثة آخرون ونالوا جميعا أكاليل بركة صلواتهم فلتكن معنا. آمين.\n- وفيه أيضا تنح القديس اؤفيلس الراهب وهو ابن وحيد لأحد أمراء جزائر روما : جاء إلى مصر طالب الرهبنة : فذهب إلى دير الزجاج بالقرب من الإسكندرية» فاستقبله القديس بقطر رئيس الدير وبعد أن اختيره ألبسه إسكيم الرهبنة. وبعد عشر سنوات جاء جنود من قبل أبيه وأخذوه رغما عنه إلى قصر أبيه؛ ولما وصل إلى هناك فرح به أبوه فوعظه اؤفيلس ليهتم بخلاص نفسه له زوال العالم» فأثر الكلام في قلبه حتى أنه نزع التاج عن رأسه تاركا الملك لأخيه وذهب هو والقديس اؤفيلس إلى دير الزرجاج وترهب هناك» أما والدة القديس فقد ترهبت بدير وقد عاش الجميع بالنسك والعبادة وعمل الفضائل إلى آخر أيامهم ولما أكمل القديس ثاؤفيلس جهاده الصالح تنح بركة صلواته فلتكن معنا. ولربنا المجد دائما أبديا آمين."},{"d":14,"t":["نياحة القديس أرشليدس الراهب","استشهاد القديسة مهراتي \"","نياحة القديس مكسيموس أ خى دوماديوس"],"b":"جو جو هوجوو - ق مثل هذا اليوم تنيح القديس أرشليدس الراذهب : ولد هذا )0 مهرا: كان للقديسة مهراتي اسم آخر هو مهرابيل. !\nالقديس ق روما من أبوين مسيحيين بارين فربياه تربية مسيحية. | توفي والده في السادسة من عمره فاهتمت والدته بتعليمه الكتاب اللقدس على بد معلم يدعى ثازفيلس فدشأ في حياة ولما كبر دخل الجندية وصار ضابطا مرموقا. بعد ذلك قرر السفر إلى أثينا ليستكمل دراسته 6 وعلى الشاطئ قبل سفره رأى جثة إنسان غريق قذفته الأمواج إلى البر ففكر في زوال العالم وانطلق إلى فلسطين ليترهب عند راهب يدعى رومانوس الذي قله وقدم له قلاية منفردة. وأقام هناك سالكا في حياة والزهد حقى بلغ درجة الكمال ومنحه الرب موهبة شفاء المرضى. ثم قطع عهدا على نفسه أن لاايرى وجه امرأة.\nحزنت والدته على فراقه فبنت فندقا لعلهاة تسمع أخبارا عن حضر بعض لجار من فلسطين فسمعتهم يتحدد دون عن راهب يشفي المرضى فسألتهم عن أوصافه فعرفت منهم أنه إلى الدير وأعلمت الأب رومانوس أنها تريد أن تقابل ابنهاء فاعتذر لها أنه لا يقابل امرأة قط ولما ألحت في الطلب الراهب أرشليدس عن وجود والدته وأنها ترغب في بإلحاح فسمح لاء ولكنه صلى إلى الله لكي لا يتخلى عنه .\nوأن يأخذ نفسنه من جسده. ولما دخلت الأم على ابنها وجدته قد فارق الحياة» فبكت بمرارة وسألت الرب أن يأخذ نفسها مع ابنها وبالفعل ركعت بجوار ابنها وفاضت روحها. وإذ أرادوا دفن الجسدين سمعوا صوتا يخرج من جسد القديس أرشليدس يقول: \" أسألكم يا إخوتي أن تجعلوا جسدي مع جسد أمي لأني 1 أسمح لما برؤيتي ونحن في الجسدء أما الآن فاتركوا الجسدين الجسدين معا بركة صلوات هذا القديس فلتكن معنا. امين.\n؟ - وفيه أيضا استشهدت القديس مهراتي. ولدت هذه القديسة في طموه ”؟ من أبوين مسيحيين تقيين» كان والدها كاهنا وقد أعطاه الله هذه الابنة أسماها مهراتي فرباها على الآداب المسيحية ولما كر دقلديانوس بالإبمانذ مضت هذه القديسة لتعلن إمانها المسيحي ولم تعلم أباها أو أمها. ولما وصلت إلى أنصنا وقفت أمام الوالي كلكيانوس فنظرها صغيرة السن فأهملها فرفعت صوتها وأعلنت أنها تؤمن بالسيد المسيح فتعجب الوالي وحاول أن يثتيها عن عزمها ولكنها تمسكت بإمانها فأمر بتعذييها 0 طموه: تبعد كيلومترا جنوب مدينة الجيزة وبها دير الشهيد أن سيفين.\nبالهنبازين ثم وضعوها على كرسي من الحديد وثنحته نار 6 وبمعونة الله صبرت على العذاب بالرغم من صغر سنها وبعد أن فشل الوالي تعذيبها أمر بحبسها ق مغارة مملوءة بالحيات والعقارب ففاضت روحها ونالت إكليل الشهادة وأغلقوا عليها ذلك المكان ولما ممع أبواها حضرا مع أجمع كثير من أهل المدينة وكفنوها ونقلوها إلى طموه - حيث بنيت كنيسة فوق جسدها الطاهر.\nبركة صلواتها فلتكن معنا. آمين.\n- وفيه أيضا من مسنة 8 للشهداء ( ) تنح القديس مكسيموس أخو القديس دوماديوس وتوجد ب سيره تحت اليوم السابع عشر من شهر طوبه.\nبركة صلواته فلتكن معنا.\nولربنا المجد دائما أبديا آمين"},{"d":15,"t":["نياحة عوبديا النبي"],"b":"في مثل هذا اليوم تن تنيح الني عوبديا وهو رابع الأنبياء الصغار الاثني عشر. كانت نبوة عوبديا نحو سنة 0/84 ق. م. بعد سقوط أورشليم وبسبب تحالف بنى أدوم مع البابليين فأنذرهم الني بأنهم من الله وهددهم الني بالخراب والدمار. كما تنبا :ل اليهود من السب ويتألف سفر عوبديا من إصحاح واحد.\nهذه النبوة تخص كل نفس متكبرة تظن أنها قادرة على الدفاع عن نفسها لسكناها في الجبال الوعرة» وأيضا النفس الشامتة بسقوط الآخرين. ض وإن كانت النبوة في ظاهرها موجهة ضد أدوم لكنها تدخل بنا إلى وهو خلاص يعقوب وتقديسه وتمنعه باليراث حيث يملك مع الرب في ملكوته بعد أن يهم قوة إبليس ويعطى النصرة للكنيسة في جهادها.\nبركة هذا الني العظيم فلتكن معنا.\nولربنا المجحد دائما أيديا أمين.\nلس .الم __ به وج"},{"d":16,"t":["استشهاد القديس فيلوثيئوس","نياحة البابا يوأنس الرابع البطريرك الثامن والأربعين من بطاركة الكرازة المرقسية"],"b":"- في مثل هذا اليوم من سنة للشهداء ( 4 ) استشهد القديس ولد هذا القديس بمدينة أنطاكية من أبوين وثنيين. دعاه أبوه في سن العاشرة ليسجد للعجل فلم يقبل؛ فتركه والده لمحبته له.\nأما القديس فكان يخاطب الشمس ويقول لها إن كنث أنت الإله صوت يقول لست أنا الها ولكننى أخدم الإله الذي سوف تعرفه وتسفك دمك لأجل اسممه. ولما رأى الرب استقامة سيرته أرسل إليه ملاكا عرفه بخلقة العالم وتجسد السيد المسيح لخلاص البشر فابتهج قلبه وبدأ يصلى ويصوم ويتصدق على الفقراء.\nوحدثت معجزة لأبويه بضلاة هذا القديس فآمنا بالسيد المسيح؛ ونالا سر المعمودية المقدسة» وقد وهبه الله موهبة شفاء المرضى فذاع حتى بلغ مسامع الإمبراطور دقلديانوس فاستحضره وأمره أ البخور للأوثان» فرفض فحاول معه بالوعد والوعيد فلم يقبل وعذبه عذابا شديدا. وأخيرا أمر بطع رأسه فنال إكليل الشهادة وتوجد له كنيستان باسمه الأولى بدير النغاميش مركز أولاد طوق شرق التابعة لإيبارشية البلينا والثانية بقرية إدفا مركز سوهاج التابعة لإيبارشية سوهاج ؛ كما توجد باسيمه كنائس أخرى.\nصلواته فلتكن معنا. أمين.\nالغف"},{"d":17,"t":["نياحة القديس دوماديوس أخي القديس مكسيموس","نياحة القديس الأنبا يوساب الأبح أسقف جرحا"],"b":", 5< وفيه أيضا من سنة 59 للشهداء 97 لام 4 تنيح البابا يوأنس الرابع البطريرك الثامن والأربعون من بطاركة الكرازة المرقسية.\nولد في قرية أبوصير ''» ترهب بدير القديس مكاريوس» وبعد أن قضى سنوات طويلة في العبادة والنسك ودراسة الكتاب المقدس والتأمل واشتهر بالنسك» ر سمه البابا ميخائيل السادس والأربعون قسا على كليسة 3 أي م مينا وكلفه برعاية شعبها فبذل والأراخنة بالإسكندرية لمدة ثلاثة أيام واظبوا فيها على : الصلاة والصوم ثم ألقوا قرعة فوقحت على الراهب يوحنا بطريركا يوم 1 طوبه سنة 597 للشهداء ( لالالام .\nاهتم هذا البابا بتعليم شعبه وافتقاده وكلف تلميذه مرقس في العناية بالفقراء والمساكين» وحدث في أيامه غلاء شديد فكان يجتمع عند قلايته فقراء كثيرون من كل ملة فكان يقضى لحم وأمر ببناء كنائس كثيرة وترميم ما تهدم منها. ولما أكمل جهاده الصاح عرف يوم نياحته إذ قال للكهنة إني ولدت أيضا أتنيح » وأوصى أن يكون تلميذه مرقس بطريركا بعده ثم تيح بسلام. 0 ض بركة صلواته فلتكن معنا. ولربنا المجد دائما أبديا آمين.\n'\" هي قرية أبوصير املق مركز الواسطى محافظة ب سويف.\nفيه» واستأذنا أباهما وذهبا إلى نيقية - في مثل هذا اليوم من سنة 48 للشهداء ( ) تنح القديس دوماديوس ابن الملك فالنتيانوس 6 تربى مع أخيه مكسيموس | وأخته تربية مسيحية حقيقية» وكان عدد من الرهبان يترددون على القصر الإمبراطوري» فأحب الأخوان مكسيموس حياة الرهبنة والوحدة » وزهدا في العالم وكل ما نيقية لزيارة المكان الذي اجتمع فيه الآباء الثلاثماثة والثمانية عشرء وهناك تقابلا مع راهب قديس امه يوحناء وكشفا له ما في قلبيهماء ففرح جدا أن يذهبا إلى سوريا ليتتلمذا على يدي القديس أغابيوس الذي كانت شهرته قد ذاعت في كل مكان.\n' ذهب القديسان مكسيموس ودوماديوس إلى سوريا وتقابلا مع القديس أغابيوس وسكنا عنده حوالي ست سنوات. وكانا .\nفي النعمة والفضيلة. ولما قربت نياحة القديس أغابيوس أن يذهبا إلى مصر ويتتلمذا على يدي القديس مكاريوس الكبير أب برية شيهيت. استمر القديسان في سوريا بعد نياحة القديس أغابيوس حق ذاع صيتهما وأرادوا رسامة مكسيموس بطريركا » فلما شعرا بذلك هربا إلى مصر وجاءا إلى القديس مكاريوس وطلبا منه أن يسنا ق مغارة» فأراهما صخرة كبيرة ليحفرا فيها المغارة؛ ثم علمهما ضفر الخوص قليلا من الخبز والملح؛ وسلمهما التداريب الروحية اللازمة لحياة الوحدة والرهبنة.\nسكن القديسان في المغارة يجاهدان في الصوم والصلاة والنسك حوالي ثلاث سنوات» وكانا يأتيان إلى الكنيسة كل يوم أحد وهما صامتان للتناول من الأسرار المقدسة. وقد كشف الرب للقديس مكاريوس مقدار قداستهما عندما ذهب حيث وجدهما يصليان طوال الليل» وكانت صلاة القديس مكسيموس تشبه حبلا من نار يخرج من فمه صاعدا إل .\nالسماء» وكانت الشياطين تحيط بالقديس دوماديوس مثل الرب يطردهم عنه بسيف من نار. ولكنهم لم على الاقتراب من القديس مكسيموس لكمال قداسته.\nمرض القديس مكسيموس بحمى شديدة وتنيح بسلام في دوماديوس وتنيح بعد أخيه بثلاثة أيام» ودفنهما القديس مكاريوس في نفس مغارتهما.\nبركة صلواتهما فلتكن معنا. أمين.\n7 - وفيه أيضا من سنة 1547 للشهداء ) تنيح القديس الأنبا يوساب الأبح أسقف جرجا وأخميم. ولد بقرية النخيلة سنة 770 م من من أبوين مسيحين ل بارين أ سمعياه يوسف وربياه على حب التقوى والفضيلة. وعكف منذ طفولته على القراءة ودراسة الكتب المقدسة. ولما كبر اشتاق إلى حياة الرهبنة؛ فذهب إلى دير القديس الأنبا أنطونيوس في سن الخامسة والعشرين من عمره» وهناك صار راهبا فاضلا. وأظهر وداعة ومحبة للحياة النسكية إلى جانب علمه الغزير وخاصة في الأمور اللاهوتية. وفي إحدى زيارات البابا يوأنس (18) لدير الأنبا أنطونيوس استدعى الراهب يوسف الأنطوني» ودار بينهما حديث طويل علم منه البابا مقدار علم الراهب يوسف ورجاحة عقله» فأخذه معه إل البطريركية وغهد إليه ببعض الأمور الإدارية فقام بها خير قبام؛ له قلب اليبانا وأقامه أسقفا على جرجا وأخميم سنة 9 و\" فاهتم بافتقاد شعبه وتعليمهم وتقويم أخلاقهسم وبث الروح المسيحية في سلوكهم كما قاوم الإرساليات الأجنبية التى بدأت بلاد الصعيد في ذلك الوقت. ولكثرة علم الأنبا يوساب كان البابا يوأنس يسند إليه الرد على رسائل بابا روماء بأسانيده اللاهوتية العميقة» كما كلفه قداسة البابا بجولة تعليمية في الأقاليم المصرية. وقد وضع هذا الأسقف الجليل كتبا ومقالات كثيرة المؤمنين في عقيد: تهم الأرثوذكسية » ولما أدركتة متاعب الشيخوخة ذهب إلى دير القدين الأنبا أنطونيوس وتنيح هناك بسلام عن عمز يناهز الواحد والتسعين عاماء وما زال جسده الطاهر كاملا محفوظا ق مقصورة ة بالدير. ل ل | بركة صلواته فلتكن معنا. ولربنا المجد دائما أبديا أمين."},{"d":18,"t":["نياحة القديس يعقوب أسقف نصيبين","تذكار مريم ومرثا أختي لتازر الحبيب","نياحة الأنيا أندراس الشهير ب ( أبو الليف )"],"b":"- ف مثل هذا ا ليوم من سنة 04 للشهد اء جم م تنيح إ لقديس يعقوب أسقف نصيين. ولد هذا القديس في مدينة نصيبين ما بين النهرين» تربى منذ حداثته على التقوى ومبة الفقراء ودرس الكتاب المقدس وبعض العلوم. أحب السيرة الرهبانية فيها للصوم والصلاة والنسك واشتهرت قداسته وذاعت فضائله ووهبه الله عمل المعجزات ولما تنيح أسقف نصييين؛ اختاره الإكليروس والشعب أسقفا عليهم سنة استمر في حياة النسك والتقشف واهتم بتعزية الحزانى وزيارة المرضى والعناية بالفقراء والأرامل والأيتام وتشييد الكنائس.\nحضر هذا الأب مجمع نيقية ووافق على قراراته وقوانينه ولما سابور ملك الفرس مدينة نصيبين وفتح في أسوارها ثغرة إلى المدينة؛ صلى هذا القديس إلى الله ليحفظ شعبه. وفي الصباح رأى سابور أن الأسوار قائمة سالمة على ما كانت عليه وأرسل الرب على جيوشه الذباب والناموس فهرب وبعد أن أكمل جهاده الصاح تنح بسلام.\nبركة صلواته فلتكن معنا. آمين.\n؟ < وفيه أيضا رمت الكنيسة تذكار القديستين مريم ومرثا أختي لعازر الحبيب الذي أقامه الرب من بين الأموات. ولدت هاتان القديستان في بيت عنيا. وكان الرب يسوع المسيح يستريح في بيت لعازر وأختيه. وقد عبرت كل من مرثا ومريم عن حبها للسيد المسيح بأسلوبها الخاص فاهتمت مرثا بضيافته والعمل على راحته أما مريم فقد جلست عند قدميه تستمع إلى كلامه © وهي أيضا دهنت قدمي المخلص بطيب غالى الثمن فامتدحها الرب قائلا ' حيثما يكرز بهذا الإنجيل في كل العالم يخبر أيضا بما فعلته هذه تذكارا لها \".\nولما مات لعازر دار حديث بين الرب وبينهما ”\" أظهرتا فيه إيمانهما بأن السيد المسيح هو ابن الله الآنى إلى العالم.\n- وفيه أيضا تنيح القديس الأنبا أندراس الشهير ب ( أبو الليف ).\nوهو من آباء الججيل السابع وكان تلميذا للأنبا بسنتاؤس أسقف ولد هذا القديس ببلدة شالهور 0 من أبوين مسيحيين كان والده فلاحا بسيطا فرباء تربية مسيحية. وكان القديس أندراس يوزع طعامه على المحتاجين ويظل صائما حتى المساء وانتهز رد سا ل ب\" ير 11 بلاحلان و ا قرية تابعة لمركز قوص محافظة قنا.\nدير أ بو الليف يقع بالقر ب من قرية حاجر دنفيق مركز نقادة محافظة قنا على بعد 78 مترا من دير فرصة رعايته لغلم أبيه للاختلاء والصلاة والحديث مع الل واشتاق إلى حياة الرهبنة. وفي سن العشرين مضى إلى دير بجبل الأساس وترهب هناك وأجهد نفسه في عبادات كثيرة ونسك؛ وأظهر محبة كبيرة لإخوته الرهبان. فحسده الشيطان وحاربه بقوة لكنه في اتضاع وبساطة وإيمان كان يقول: \" الله الذي أعطى القوة والنصرة لآبائنا القديسين أنطونيوس ومكاريوس هو من شر هذا العالم الزائل \" ولما حاربه بترك الرهباني لنوال وظائف العالم قال: ' ماذا ينتفع الإنسان لو العالم كله وخسر نفسه \". وكان يتحصن دائما بعلامة الصليب فيهرب منه الشيطان.\nلما سمع الأنبا بسنتاؤس أسقف قفط بفضائل هذا القديس تلميذا له. وقد أعطاه الله موهبة شفاء الملرضى وعمل فكانت الجموع تلجا إليه وتطلب إرشاداته وصلواته.\nوبعد أن أكمل جهاده تنيح بسلام ودفن في الدير الذي حمل اسمه فيما بعد © . وقد ذفن في ثوب من الليف لذلك دعي اسمه ( أبو بركة صلواته فلتكن معنا.\nولربنا المجد دائما أبديا آمين."},{"d":19,"t":["اكتشاف أعضاء القديسين أباهور وبيسوري وأمبيرة أمهما"],"b":"000 ووو فو وفوف وووخوف وهف في مثل هذا اليوم من سنة 04 للشهداء )؛ كان اكتشاف أعضاء القديسين أباهور وبيسوري وأمبيرة أمهماء من أهل الشهداء مركز دسوق واستشهدوا زمن عبادة الأوثان ووضعت أجسادهم في كنيسة بلدهم.\n0 ولما غرت الحملة الصليبية الخامسة مصر وملكوا مدينة دمياط وما من البلاد؛ خرج إليهم الملك الكامل ملك مصر بجيوشه؛ وأثداء مرورهم على البلاد هدموا وخربوا بعض الكنائس ومنها كنيسة شباس الموضوع فيها أجساد هؤلاء القديسين. فأخذ أحد الجنود تابوت القديسين ظنا منه أنه سيجد فيه مالا ينتفع به؛ فلما وجد هذه الجواهر الكريمة التى لا يعرف قيمتهاء فطرحها بجوار حائط الكنيسة وأخذ التابوت وباعه» أما الأعضاء النفيسة فوجدتها امرأة أحد الكهنة فأخذتها ووضعتها داخل الكنيسة وغطتها بكمية من هكذا نحو عشرين سنة» ولما أراد الله إظهارها تذكرتها المرأة وأعلمت المؤمنين بمكانها فجاء الكهنة وكشفوا عنها ثم وضعوها في تابوت جديد داخل. الكنيسة. وظهرت منها آيات وأشفية كثيرة.\nبركة 'صلوات هؤلاء القديسين فلتكن معنا.\nولربنا المجد دائما أبديا آمين.\n)0 الفنت: قرية تابعة لمركز الفشن بمحافظة بئ سويف."},{"d":20,"t":["نياحة القديس بروخورس أحد السبعين رسولا","استشهاد القديس أبا كلوج القس","استشهاد القديس بهناو","تذكار تكريس كنيسة القديس يوحنا صاحب الإنجيل الذهب"],"b":"- في مثل هذا اليوم تنح القديس بروخورس أحد السبعين رسولا الذين اختارهم الرب يسوع» وهو أحد الشمامسة السبعة الذين الرسل وشهد لهم أنمم ممتلشون من الروح القدس والحكمة » وهو قريب القديس إسطفانوس رئيس الشمامسة وأول الشهداء» وقد صاحب القديس يوحنا اللاهوتي في أغلب جولاته فأقامه أسقفا على مدينة نيقوميدية فبشر أهلها بالسيد المسيح وعمد من أمن منهم واحتمل ضيقات كثيرة بسبب خدمته وكرازته. ولما أكمل سعيه الصالح تنيح بسلام.\nبركة صلواته فلتكن. معنا. امين. | - وفيه أيضا من سنة 18 للشهداء ( 4 م )؛ استشهد القديس أباكلوج القس» الذي من بلدة الفنت ')» من أبوين مسيحيين؛ كان والده ديوسقوروس وأمه أوفومية» ربياه تربية مسيحية وتعلم العلوم الكنسية في كاب القرية» وظهرت عليه علامات القداسة منذ صغره» وكان عطوفا على الفقراء محبا للمساكين.\nولما رأى الشعب كثرة فضائله» قدموه إل الأب الأسقف فرسمه قسا على كنيسة القرية» وأثناء الرسامة سمع الجميع صوتا يقول \" مستحق.. مستحق.. مستحق\"» ورعى شعبه بأمانة واستقامة حق انتشرت رائحة سيرته الزكية في كل مكان. واشتهي | القديس يوليوس الأقفهصي أن يراه 6 فجاء إليه. مع بعص غلمانه وتبارك منه ثم أخذه إلى قريته أقفهص )0 حيث ظل فيها أيام ثم عاد إلى بلده.\nاشتد الاضطهاد دعلى المسيحيين 4 وجاء إريانوس الوالي إلى الناس على عبادة الأوثان 6 ولما أحس أباكلوج 0 بقدومه» جمع شعبه ق الكنيسة وأقام هم قداسا ووعظهم على الثبات في الإيمان حت النفس الأخبر. ثم ذهب إلى إريانوس واعترف أمامه بالسيد المسيح فقبض عليه وحاول أن يغريه العالية فرفض» فتوعده بأشد أنواع العذاب ولكن القديس استهان بالعذاب ثبت على إمانه المستقيم» فعذبه الوالي بعذابات كثيرة» وأخذه إلى أهناسيا ' حيث أعاد محاكمته وتعذيه؛ وكان ملاك الرب يقويه ويشدده» وحدثت منه بعض المعجزات فأمر الوالي بإعادته إل بلده وقطع رأسه هناك ونال إكليل الشهادة؛ ومازال جسده يوجد في أنبوبة في الكنيسة التي تحمل اسمه بالفنت.\nبركة صلوات القديس أبا كلوج فلتكن معنا. آمين.\n!© أقفهص: قرية مازالت بنفس اسمها بجوار الفنت.\nمدينة أثرية قديعة تقع على بعد 4 7 كيلومترا غرب مدينة بئ سويف.\n- وفيه أيضا استشهد القديس بهناو.\nبركة صلواته فلتكن معنا امين.\nوفيه أيضا تذكار تكريس كنيسة القديس يوحنا الكوخي صاحب الإنجيل الذهب؛ بمدينة روماء ونقل جسده إليها من القسطنطينية» وتجد خبر نياحته تحث اليوم السادس عشر من شهر أبيب. | بركة صلواته فلتكن معنا.\nولربنا المجد دائما أبديا آمين."},{"d":21,"t":["نياحة والدة الإله القديسة مريم العذراء","نياحة القديسة إيلارية ابنة الملك زينون"],"b":"- ق هذا اليوم من سنة يم م تتبحت القديسة الطاهرة مريم العذراء والدة الإله حيث عاشت بعد صعود ربنا بسو المسيح إلى السماء ف بيت إ لقديس يوحنا الحبيب» خمس عشرة سنةف كانت تتردد على القبر المقدس كثيرا وتصلى هناك فعلمت بالروح القدس بموعد انتقالها ففرحت» فاجتمع الآباء الرسل السيدة «العذراء 6 مم جاء السيد المسيح بنشنسشه مع ملائكته القديسين. واستلم روحها الطاهرة وصعد بها إل السماء» أما جسدها الطاهن فكفله الآباء الرسل وحملوه إلى جبل يهوشافاط وف الطريق حاول أحد اليهود منعهم من ذلك وأمسك بالتابوت» فانفصلت يداه عن جسده وبقيتا معلقتين ؛» فندم وبكى على سوء فعله» وبتوسلات الآباء الرسل القديسين عادت يداه كما كانت» فآمن لوقته بالرب يسوع» ثم أكمل الرسل سيرهم حتى وصلوا الجثمانية ودفنوها هناك بإكرام جزيل وكانت سنو حياتها على الأرض نحو ستين عاما.. ض شفاعتها المقدسة فلتكن معنا. آمين.\n7 - وفيه أيضا من سنة 774 للشهداء ( ) تتحت القديسة البارة إيلارية الناسكة ابنة الملك زينون» ولدت هذه القديسة في أواخر القرن الخامس » فرباها الملك زينون هي وأخت لما اسمها تربية -مسيحية حقيقية. وكانت إيلارية كثيرة الميل إلى البتولية » لها اشتياق للرهبنة» ولم ترد أن تذهب إلى أحد أديرة العذارى القريية من القسطنطينية لعلمها أنها لن تقبل هناك خوفا من أبيها؛ وكانت تفكر وتصلى كثيرا ليدبر الرب حياتها.\nبزئ الرجال وسافرت في سفينة إلى الإسكندرية؛ ثم الإسقيط حتىق وصلت إلى دير القديس مكاريوس الكبير» وتقابلت مع الأنبا بموا وأخبرته عن قصتهاء منه أن يسمح لا بالإقامة عنده» فقبلها راهبا وأسكنها في مغارة عن الدير حيث ظلت بها خمس عشرة سنة تتعبد بنسك شديد وكان الأنبا بموا يفتقدها بين حين وآخرء أما هي فلم إلى الدير إلا للتناول من الأسرار المقدسة. ولما لم تظهر لها إيلاري الخصي.\nحدث أن اعترى أختها الصغرى شيطان رديء» فأرسلها الملك إلى البرية ليصلى لها الآباء الرهبان ببرية شيهيت» فلما وصلت إل الدير صلى لها الرهبان أياما كثيرة فلم تبراء وأخيرا إيلاري الخصي ليصلى لهاء فأخذها وظل حتى برئت. ثم أحضرها إلى الشيوخ فأرسلوها إلى الملك وكيف كان حالما في شيهيت» فقالت له أن القديس الذي أبرأها بصلاته كان يعانقها كثيرا» فلم يسترح الملك لسلوك الراهب إيلاري تجاه فأرسل إلى شيوخ البرية قائلا أرسلوا لي القديس إيلاري فلما وصل اختلى به الملك والملكة كيف كنت تعانق وتقبل الأميرة. فقال لهم الراهب لي الإنجيل وتعهدا عليه أنكما لا تعيقاني عن العودة إلى البرية إذا قلت لكما الحقيقة فلما تعهدا له بذلك قال \" أنا إيلاري ية \" ففرح الملك والملكة وكل القصر الملكي 7 شيهيت 6 فلم يرد والداها أن يطلقاها إلا بعد أن ذكرتهما فكتب الملك إلى والي مصر يأمره بأن يقدم للدير كمية كبيرة من القمح والزيت وكل احتياجات الرهبان سنويا. واهتم الملك بعمارة البرية وأنشا بدير القديس مكاريوس حصنا عظيما لا يزال قائما إلى الآن.\nوبعد رجوع إيلارية إلى البرية» عاشت اشنتي عشرة سنة على الدسك والعبادة ثم فاضت روحها الطاهرة؛. .\nفصلى عليها الرهبان ودفنوها بإكرام جزيل.\nالبركة صلواتها فلتكن معنا.\n. ولربنا امجد دائما أبديا آمين.\nةكلضر"},{"d":22,"t":["نياحة القديس العظيم الأنبا أنطونيوس أب جميع الرهبان"],"b":"مثل هذا اليوم من سنة 77 للشهداء ( 07 \"ام ) تنيح القديس العظيم الأنبا أنطونيوس كوكب البرية وأب جيع الرهبان.\nولد هذا القديس سنة في بلدة قمن العروس \"؟ من أبوين غنيين محبين للفقراء فربياه في مخافة الله مات والده فوقف أمام زوال العالم. والتهب قلبه نحو الأبدية وقال ' ' أين همتك العظيمة وجمعحك للمال. إني أرى الجميع قد بطل وتركنه. إن كلت قد خرجت أنت بغير اختيارك فلا أعجبن من ذلك بل أعجب أنا من نفسي إن عملت كعملك \". وكان يتأ مل ف أعمال | لآباء الرسل وكيف تركوا كل شيء وتبعوا المخلص ”\"» وكيف كان الناس على المحتاجين 7 . وفي ذات يوم دخل إلى الكئيسة كعادته فسمع الإنجيل يقول: \" إن أردت أن تكون كاملا اذهب وبع كل مالك للفقراء فيكون لك كنز في السماء وتعال اتبعني \"9 فكان هذه ا لآية وقعها العميق ف قلبه. فمضى وباع كل ما يملك 6 وأبقى لأخته نصيبها وأودعها ق بيت للعذارى 6 ووزع ما خصه على ') قمن العروس: قرية بمركز الواسطى محافظة بن سويف.\nتن أع يي - رن الفقراء والكنائس. ثم خرج من القرية وسكن في كوخ صغير بجوار النيل وكان يتردد على النساك المجاورين يتعلم من كل واحد الفضيلة التي اشتهر بها. وبعد مدة عبر النيل وسكن في مقبرة فرعونية قديمة على الشاطئ الشرقي للنبل » وسمي المكان فيما بعد \" دير الجميزة \" أو \"دير بسبير\" وهو الآن \" دير الميمون ' وهناك لاقى حروبا شديدة من الشياطين» منها أنهم ضربوه ضربا شديدا حتى فقد » فحمله أصدقاؤه إلى الكنيسة حتى تماثل للشفاء». ثم رجع إلى بعد ذلك في الصحراء الشرقية إلى أن وجد عين ماء فسكن في مغارة وداوم على الصوم والعبادة ومقاومة حروب الشياطين » وكان الله يساعده لينتصر عليها. واستمر القديس على هذا الحال عشرين سنة واجتمع حوله أناس كثيرون ليتتلمذوا على يديه وأخرون يطلبون الشفاء من أمراضهم. فخرج إليهم القديس كثيرا من إرشاداته وصنع الله على يديه آايات وأشفية وتتلمذ له كثيرون وسكنوا مغارات كثيرة حول مغارته؛ وصار أب ومرشدا همء وبذلك أسس أول نظام رهباني في العام كله حتى دعي بحق أنطونيوس أب الرهبان.\nنزل إلى الإسكندرية مرتين» الأولى سنة م أثناء اضطهاد مكسيميانوس قيصر ليشجع المؤمنين على الثبات في الإبمان وكان يزور المسجونين ويقوى عزائمهم. والثانية سنة ليدافع عن الإيمان القويم إلى جوار البابا القديس أثناسيوس الرسولي ضد الأريوسيين.\nلقف كان يحترمه الملوك ويكرمه كل الناس. ذهب إليه في إحدى المرات بعض الفلاسفة يناقشونه فانذهلوا من علمه وذكائه الفطري. ولما بلغت أخبار قداسته إلى الإمبراطور قسطنطين كتب له رسالة مظهرا العظيم لرؤيته ؛ وطالبا الصلاة من أجله ومن أجل المملكة. فرد عليه القديس برسالة باركه فيهاء طالبا السلام للمملكة وللكنيسة» وأوصاه فيها بما فيه خلاص نفسه ونجاح مملكته. ض :\nولما ذنت نياحة القديس الأنبا بولا أول السواح مضى إليه الأنبا أنطونيوس بتدبير إلهي وكفنه ثم صلى عليه ودقتة. --.\nزاره القديس مكاريوس فألبسه زى الرهبنة؛ ثم رجع إلى برية شيهيت وأسس الرهبنة فيها. وفي أواخر أيام الأنبا أنطونيوس كان له تلاميذ كثيرون في مناطق مختلفة من مصرء مثل شيهيت؛ ونترياء النقلون بالفيوم» كان يفتقدهم أحيانا إما بنفسه أو برسائله؛ وله عشرون رسالة بهذا الصدد.\nولما أكمل جهاده الصالح جع أولاده وأوصاهم بالثبات في الجهاد الرهباني » كما أوصاهم أن يعطوا عكازه للقديس مكاريوس 0 للقديس أنناسيوس الرسولي 6 ولوب الجلد الخاص به للقديس سيرابيون تلميذه . كما أوصاهم بإخفاء جسده نعد نياحته.\nثم رقد على الأرض وفاضت روخه في يدي الرب الذي أحبه» وهو\" بشيخوخة حسنة» ومضى إلى محل إ لنياح إ لأبدي. وكا ل عمره عند نياحته مائة وخمس سنين. ا بركة صلواته فلتكن معنا. ولربنا المجد دائما أبديا آمين."},{"d":23,"t":["استشهاد القديس تيموثاوس تلميذ القديس بولس الرسول وأسقف أفس","نياحة البابا كيرلس الرابع أبى الإصلاح البطريرك المائة والعاشر من بطاركة الكرازة المرقسية"],"b":"- ل مثل هذا اليوم من سنة 5/ م استشهد القديس تيموثاوس تلميذ القديس بولس الرسول وأسقف أفسس. ولد هذا القديس في لسنيرة بآسيا الصغرى من أب يونا وأم يهودية. ربته أمه على حياة التقوى والإيمان ودراسة الكتب المقدسة» وفي ذلك يقول له القديس بولس: \" إذ أتذكر الإيمان العديم الرياء الذي فيك الذي سكن أولا في جدتك لوئيس وأمك أفنيكي. ولكنني أنه فيك أيضا \" '؟ وأيضا قوله: \" وأنك منذ الطفولية تعرف الكتب المقدسة القادرة أن تحكمك للخلاص بالإيمان الذي في المسيح يسوع \" . آمن القديس واعتمد على يد القديس بولس الرسول وصار تلميذا له كما صحبه في أغلب ثم أقامه أسقفا على مدينة أفسس عندما رأى في النعمة. ا له رسالتين الأولى سنة يوضح فيها الرعوية وبعض التنظيمات الكنسية» والثانية سنة لام فيها على الجهاد من أجل حفظ الإيمان. ولشدة نشاطه الرعوى حييث جذب الكثيرين من الوثنيين إلى المسيحية؛ قام !© لتى 5:1.\nاتى : يلد عليه الأشرار من اليهود والوثنيين وضربوه بالعصي حتى فاضت روحه بأفسس» فدال إكليل الشهادة. فأخذ المؤمنون جسده الطاهر ودفنوه بإكرام جزيل.\nبركة صلواته فلتكن معنا. امين.\n7 - وفيه أيضا من مسنة 161/7 للشهداء ) تنيح البابا كيرلس الرابع البطريرك المائة والعاشر من بطاركة الكرازة المرقسية» والمعروف بأبي الإصلاح. ولد هذا القديس ببلدة شرق التابعة لأخميم سنة واهتم والده بتعليمه العلوم الكنسية. فنما على حب الفضيلة والتقوى؛ واشتاق إلى حياة الرهبنة فذهب إلى دير القديس الأنبا أنطونيوس وصار راهبا باسم داود الأنطوني ولما ذا صيث علمه وفضائله رحمه البابا بطرس الجاولي البطرير ) 4 قسا ثم عله رئيسا للد ير؛ 8 حسن تدبيره واعتنى بتعليم الرهبان» ثم أرسله البابا بطرس الجاولي إلى الحبشة لفض التزاع بين اران والشعب : وأثداء وجوده هناك تنيح البابا بطرس الجاولي سنة دما م » وبعذد خلاف دام نحو عام بخصوص إقامة بطريرك للكنيسة» قام الأساقفة برسامة الراهب القس داود الأنطوني مطرانا عاما في أبزيل باسم الأنبا كيرلس. ولما شئون ا لكنئيسة أ أجلسوه بطريركا سنة م فاهتم بنشر التعليم : وأقام المدارس للبنين والبنات . ؛» كما أهتم كما قام بتجديد الكنيسة المرقسية الكبرى بالأزبكية بالقاهرة؛ واهتم بكافة شئون الكنيسة وقام بسيامة بعض الآباء الأساقفة.\nكذلك زار الحبشة لافتقاد الكنيسة هناك. وبعد جهاد شاق رقد في الرب» فحزنت عليه الأمة كلهاء ودفن بالكنيسة المرقسية بالقاهرة 6 بعد ان جلس على الكرسي المرقفسي نحو سبع سنوات» ولكثرة أعماله لقبته الكنيسة بأبي الإصلاح.\nبركة صلواته فلتكن معنا.\nولربنا المجد دائما أيديا آمين."},{"d":24,"t":["نياحة القديسة مريم الحبيسة الناسكة","استشهاد القديس بساده القس"],"b":"- في مثل هذا اليوم تتحت القديسة مريم الحبيسة الناسكة» وللذت هذه القديسة بالإسكندرية من أبوين مسيحيين غنيين» فربياها تربية مسيحية» وطلبها كثيرون من أولاد العظماء للزواج فلم تقبل. ولما والداها وزعت كل ما تملك على الفقراء والمساكين ثم مضت بأحد أديرة الإسكندرية . فأجهدت نفسها بعبادات كثيرة مده خمس عشرة سلة 6 ثم لبست إ لإسكيم إ لمقدس 6 وجعلت من الشعر. وبعد ذلك استأذنت رئيسة الدير وحبست نفسها في قلايتها وأغلقت بابها عليها وجعلت فيها طاقة صغيرة منها حاجاتها الروحية والجسدية. وكانت تصوم يومين يومين» وتفطر على الخبز اليابس» وني الأربعين المقدسة كانت كل ثلاث ثة أيام » هكذا قضت بالقلاية اثنتين وعشرين سنة.\nوف يوم عيد الغطاس المجيد طلبت قليلا من ماء اللقان» يديها ووجهها وتناولت من الأسرار المقدسة,؛ وبعدها مرضت » واستدعت الأم الرئيسة والراهبات لتودعهن. شم تنيحت بسلام فحملنها إلى الكنيسة وصلوا عليها ووضعنها مع أجساد العذارى القديسات.\nبركة صلواتها فلتكن معنا. أمين.\n7 وفيه أيضا من سنة 7 للشهداء ( ل ) استشهد القديس بساده القس. كانت والدته ابنة أحذ كهنة الأوثان من إهريت '\"؛ ولكنها آمنت بالسيد المشيح. ولما تقدم ابن كاهن وثنى للزواج منها هربت إلى القيس ”\"» وهناك تزوجت بمزارع» فرزقهما الله هذا القديس. فريياه خوف الله وحفظ وصاياه. ولما بلغ عمره عشرين سنة توي والده تاركا له أموالا كثيرة : فصار يتصدق مها على الفقراء. وازداد ق والتقوى : فرسموه فسا ولما كفر دقلديانوس بالابمان » نادى القديس بساده صوت من السماء قائلا: ” لماذا هذا التواني والإكليل معد ؟ \". فقام مسرعا وتقدم إل الوالي واعترف بإيمانه بالسيد المسبح» فأمر الوالي بتعذييه بالضرب بالسياط والدبابيس وخلع الأظافر وغمس أصابعه في الخل والجير وكان الرب يسنده ويشفيه. ثم أرسله الوالي إلى الفيوم» وهناك أقام طفلا من الموت كان قد سقط عليه حجر كبير. وأمام والي الفيوم اعترف ثانية بإيمانه المسيحي الصحيح. فعذبه الوالي كثيرا وكان الرب يقويه ويقيمه سالا. فضجر الوالي منه وأرمسله إلى أرمانيوس والي الإسكندرية فاعترف أمامه ثالثة بإيمانه» فأمر بقطع رأسه ونال الشهادة.\nفأخذ جسده القديس يوليوس الأقفهصى وأرسله إلى إهريت حيث دفن بكرامة عظيمة. وقد أظهر الله من جسده عجائب كثيرة.\nبركة صلواته فلتكن معنا. ولربنا المجد دائما أبديا آمين.\n'؟ إهريت: هي قرية الشيخ فضل الحالية مركز بي مزار محافظة المنيا.\nقرية تتبع مركز بن مزار محافظة المنيا."},{"d":25,"t":["نياحة القديس بطرس العابد","استشهاد القديس أسكلاس"],"b":"1- ق مثل هذا اليوم تنيح القديس بطرس العابد. كان ف أول أمره قاسى القلب عديم الرحمة بالفقراء؛ وذات يوم جاء إليه فقير يطلب صدقة بإلحاح ول يرذ أن يعطيه شيئا واتفق وصول خادمه الطعام إليه فتناول خبزة وضرث بها الفقير على رأسه حقى لا يعود إليه مرة أخرى. وفي الليل رأى في نومه رؤيا كأنه في اليوم الأخير وقد نصيب الميزان والشياطين تقدموا ووضعوا خطاياه في كفة الميزان اليسرى ثم حضرت جاعة من الملائكة بجوار كفة الميزان اليمنى وبدت عليهم الحيرة لأنهم لم يجدوا ما يضعونه فيها من أعمال صالحة فتقدم أحدهم ووضع الخزة التي كان قد ضرب بها رأس الفقير وقال: \" ليس لهذا الرجل سوى هذه الخبزة \". فاستيقظ بطرس من نومه فزعا مرعوبا - فأخذ يلوم نفسه على ظليه وقساوته فباع كل أملاكه ووزع أمواله على الفقراء والمحتاجين» ولما لم يبق له شيء يوزعه على الفقراء باع نفسه كعبد وتصدق بالثمن على الفقراء» ولما اشتهر أمره هرب إلى برية شيهيت وترهب وسار سيرة حسنة أهلته لأن يعرف يوم انتقاله فاستدعى الرهبان وودعهم وتنيح بسلام.\nبركة صلواته فلتكن معنا. آمين.\nوفيه أيضا استشهد القديس أسكلاس. نشأ هذا القديس في منطقة أنصنا وفي إحدى زيارات إريانوس وال أنصنا لبلدته استدعاه وأمره أن يبخر للأوثان فتمسك بإيمانه بشجاعة وثبات.\nأمر الوالي بربطه في حصان يجرى به في الشوارع حتى تهرا جسده لحمه ثم أمر الوالي أن توضع مشاعل نار في جنبيه وبطنه وكان الرب يشفيه ويعزيه. ركب إريانوس سفينة ليعبر النيل وأخذ أسكلاس معه وفي السفينة صلى أسكلاس إل الله أن يعمل عملا يتمجد به اسم الله أمام إريانوس وللوقت توقفت : ى| ا : لسفينة وسط الزنهر وكأها استقرت على شاطىء رملي حاول الجنود أن يحركوها فلم يستطيعوا فطلب إلى أسكلاس أن يصلى إلى إلهه لتتحرك السفيئة فلما صلى تحركت السفينة في الخال لكن الوالي تقسى قلبه فربط في عنقه حجرا كبيرا وألقاه في الليل فاستودع زوجه الطاهرة في يدي الرب ونال إكليل بركة صلواته فلتكن معنا.\nولربنا المجد دائما أبديا آمين."},{"d":26,"t":["استشهاد التسعة والأربعين شهيدا شيوخ شيهيت","استشهاد القديس بجوش","نياحة القديسة أنسطاسية"],"b":"- في مثل هذا اليوم من سنة للشهداء (22 م ) استشهد التسعة والأربعون شيوخ شيهيت. وذلك أن الملك تئودوسيوس الصغير لم ب يرق نسلا فأرسل إلى شيوخ برية شيهيت رسولا يدعى لكي يصلوا من أجله ليعطيه الله نسلا فأبلغوه أن الرب لن يعطيه نسلا للا يشارك المتدعين والهراطقة 6 وكان لمارتينوس ابن وحيد ييدعى زيوس أخذه معه إلى البرية» وبعد استشارة الشيوخ عزم على العودة إلى بلده. ولكن هجم البربر على البرية فدعا أحد الشيوخ بقية الآباء لكي يهربوا إل ال من البربر ومن يريد الاستشهاد فلييق معه فبقى معه ثانية وأربعون شبخا البربر ونالوا أكاليل الشهادة. وشاهد الصبي زيوس الملائكة تضع الأكاليل النورانية على رؤوس الشيوخ الشهداء فقال لأبيه أنا ماض لأنال إكليلا فأجابه والده وأنا أيضا أذهب معك وللوقت للبربر فقتلوهما ونالا إكليل الشهادة. 0 وبعد أن مضى البربر نزل الرهبان من الحصن وأخذوا أجساد الشيوخ الشهداء بإكرام جزيل ووضعوها في مغارة خارج الدير ولما توالت غارات البربر نقل الرهبان الأجساد الطاهرة وبنوا لهم كنيسة داخل دير القديس مكاريوس الكبير قام بتكريسها البابا ثيثودوسيوس الأول البطريرك 7 سنة ثم بنى المعلم إبراهيم يم الجوهري كنيسة خاصة مم سنة داخل الدير ونقل الأجساد الطاهرة إليها وسميت كنيسة الشيوخ.\nبركة صلواتهم فلتكن معنا. آمين.\n- وفيه أيضا استشهد القديس بجوش. كان رجلا غنيا با للفقراء والمساكين» ولما أثار دقلديانوس الاضطهاد على المسيحيين ظهر رئيس الملائكة ميخائيل ودعاه أن يشهد للسيد المسيح أمام الوالي فقام بتوزيع كل ممتلكاته على الفقراء وذهب إلى الوالي يعلن الوالي كثيرا لعله يرجع فتمنك بإيمانه فألقاه في السجن» ولما سجمعت' والدته جاءت تعاتبه كيف يتركها دون أن يشركها في إكليل الشهادة وبقبت معه طوال الليل يصليان”.\nمعا لكي يهبها الله إكليل الشهادة وفي الصباح استدعى الوالي القديس بجوش فكانت أمه تسير معه وتعلن إيمانها فأمر الوالي أما القديس فعذبه الوالي بعذابات كثيرة وأخيرا أمر بقطع رأسه فنال إكليل الشهادة وقد تم ذلك بقرية طما التابعة لقاو 9 بركة صلواته فلتكن معنا. آمين.\nطما هي الآن إحدى مدن محافظة سوهاج؛ أما قار فكانت مدينة هامة ومركز كرسي وعاصمة ولاية في العصور السابقة أما الآن فهي قرية \" كوم إشقاو \" التابعة لمركز طما محافظة سوهاج.\nوهي غير قرية قاو النواورة التابعة لمحافظة أسيوط. :\n- وفيه أيضا من سنة 197 للشهداء ( ) تشحت القديسة أنسطاسية. كانت من أعرق العائلات الغنية في مدينة القسطنطينية.\nولما أراد الملك جوستنيان الزواج منها رغم زواجه من ثيودورا أنسطاسية الملكة بذلك فساعدتها على الهروب إلى مصر في سفينة خاصة. وبنت لها ديرا بالقرب من الإسكندرية؛ وكان القديس ساويرس يرسل لا رسائل روحية لتعزيتها ولكن الملك كان يطاردها في كل مكان لكي يتزوجها فارتدت ملابس"},{"d":27,"t":["تذكار رئيس الملائكة الجليل سوريال","استشهاد القديس أبى فام الجندي الأوسيمي. غ","استشهاد القديس سيرابيون. 5","تذكار نقل جسد القديس تيموثاوس تلميذ معلمنا القديس بولس الرسول"],"b":"ض - في هذا اليوم تعيد الكئيسة بتذكار رئيس الملائكة الجليل الرجال وسمت نفسها أنسطاسي الخادم وجاءت إلى برية شيهيت وتقابلت مع الأنبا دانيال قمص البرية وأطلعته على أمرها فقبلها واختار لها مغارة بالبرية الداخلية وعاشت فيها وكان ذلك سنة عاشت أنسطاسية في هذه المغارة 74 سنة دون أن يعرف أحد عنها شيئا وكان الأنبا دانيال يرسل لها تلميذه أسبوعيا بالطعام ويأخذ رسائلها التي كانت تكتبها على شقفة من الخزف إل الأنبا دانيال دون أن يقرأها. وفي إحدى المرات أتى .\nالتلميذ بالشقفة إلى الأنبا دانيال فلما قرأها بكى وقال لنذهب إل المتوحد فذهبا كلاهما إلى المغارة وهناك وجداها بحمى شديدة وقالت سوريا ل 6 أحد السبعة رؤساء الملائكة وهشو أحد السبعة 0 الأرواح التي أمام عرش الله 0 وموطنهم ف السماء ولكنهم لخدمة بنى البشر حيث أن \" ملاك الرب جال حول \" '\". وهم \" أرواح خادمة مرسلة للخدمة لأجل العتيدين أن يرثوا الخلاص \" !\". خلقهم لله أرواحا لها طبيعة شفافة ترى الله ولكن على قدر ما تحتمل.\nورئيس الملائكة سوريال ( الذي معنى اسمه بوق الله )؛ سوف يبوق في اليوم الأخير حين يرسل الله ملائكته ببوق عظيم الصوت فيجمعون مختاريه من الأربع الرباح من أقصاء للأنبا دانيال من أجل الله لا تكنى بل اتركني بملابسي ثم صلت السماوات ل أقصائها \"'.\nبسلام ففاضت رائحة بخور طيبة في المغارة ولاحظ التلميذ أنها امرأة فتعجب وسكت وبعد أن ذفناها رجعا إلى موضعهما ا : رز 0 1 فب\" : ع 0\" 2 مز لا ل 0 0 وطلب التلميذ من معلمه أن يعرفه قصتها فأخبره بسيرتها : إ | \"عب 4:1 : 7 | بركة صلواتها فلتكن معنا. ولربنا المجد دائما أبديا أمين. “لزنا | ذ ب مت 3:76 بنى له القديس يوحنا ذهي الفم كنيسة عظيمة بالقسطنطينية وكرسها باسمه في اليوم السابع والعشرين من شهر طوبه؛ وحدثت منها معجزات كثيرة بشفاعته.\nشفاعته فلتكن معنا. أمين.\n7- وفيه أيضا من سنة 30 للشهداء (4 م ) استشهد القديس أبو فام الخخدي. ولد هذا القديس بأوسيم \" من أبوين غنيين 6 ربا ل تربية مسيحية 6 فشب على خوف ا لله م جوم والشفقة على المساكين» مواظبا على الصلاة والصوم. وعرض عليه أبواه الزواج فلم يقبل. . ولا كفر دقلديانوس وأعلن الاضطهاد على المسيحيين؛ تقدم القديس إلى والي المنطقة واعترف أمامه بالسيد المسيح فعذبه كثيرا وتصادف وجود إريانوس والي أنصنا بأوسيم فأخذ القديس معه إلى قاو وهناك في ذيل حصان وظاف به المدينة كلها ثم أمر بعصره في وكان الرب يشفيه ويقويه؛ وبعد لك أمر الوالي إريانوس بربط حجر في عنق القديس وإلقائه في النهر. فأرسل الرب ملاكه وأنقذه من الغرق. فاستشاط الوالي غيظا وأمر بوضع القديس في أتون نار» فلم تؤذه النار وصارت كندى بارد وأخيرا أمر الوالي بقطع رأسه فنال إكليل الشهادة. وأخذ بعض المؤمنين جسده الطاهر وكفنوه بإكرام جزيل ودفنوه بمدينة أوسيم: أحد مراكز محافظة الجيزة.\nما وبنيت له كنيسة باسمه؛ وقد ظهرت من جسده آيات بركة صلواته فلتكن معنا. آمين.\n- وفيه أيضا من سنة 7 للشهداء ( م ) استشهد القديس.\nهذا القديس بمصر» من أبوين مسيحيين غنيين.\nفنشا محبا للفقراء والمساكين. ومع عن تعذيب المسيحيين بالإسكندرية» فمضى إليها ومعه صديق يدعى اؤدورس وأحد | رعاة غنمه اسمه توماء وهداك تقدموا إلى أرمانيوس الوالي واعترفوا بالسيد المسيح» فأمر بطرحهم في السجن. ثم عذ في التبازين» وطرحهم في قطران مغلي» وصابه» وكان ملاك الرب يقيمهم سالمين من جميع هذه العذابات ويشددهم ويقويهم. . ولما تضايق الوالي أمر رئيس المدعو أوريون أن يقطع رأس القديس سبرابيون» فنال بركة صلواته فلتكن معنا. أمين.\n4 - وفيه أيضا تحتفل الكنيسة بتذكار نقل جسد القديس تيموثاوس أسقف أفسس وتلميذ معلمنا القديس بولس الرسول؛ من أفسس إلى القسطنطينية بأمر الإمبراطور قسطنطين الكبير» حيث وضعوه بإكرام عظيم داخل كنيسة الآباء الرسل القديسين وتجد خبر استشهاد القديس تيموثاوس تحت يوم »7 طوبه.\nبركة صلواته فلتكن معنا. ولربنا المجد دائما أبديا أمين:"},{"d":28,"t":["استشهاد القديس الأنبا كاؤو","استشهاد القديس إكليمنضس أسقف أنقرة","استشهاد القديس فيلياس أسقف تمي الأمديد"],"b":"1- في مثل هذا ا ليوم من سنة أ للشهد إ \" م ' سس اأستشهد القديس كاؤو الناسك» ولد هذا القديس بلدة دكوشيه نب أواخر القرن الثالث الميلادي » وكان محبا قرام والتأمل في ق الكتاب المقدس 4 فمضى وسكن ف مغارة بصحراء الفيوم ولما ثار الاضطهاد على المسيحيين» ظهر له ملاك الرب في الرؤيا وقال له: \" لماذا أنت جالس هنا والأكاليل معدة للشهداء 4 قم اذهب إل اللاهون واعترف هناك باسم السيد المسيح \".\nوللوقت قام ومضى إلى المدينة» فوجد هناك رسول الوالي؛ الذي أعجب بشيبته وحسن منظره» فأكرمه وأجلسه 3 ثم أخرج له صنما من ذهب مرضعا بالأحجار الكريمة» وقال له هذا الملك لوالي أنصنا فأخذه القديس ثم طرحه على الأرض فغضب رسول الوالي وأمر الجنود فربطوا القديس 6 وأخذه معه إل والى أنصناء وهناك قدمه للوالي ة ذبه كثيرا بضربه وعصره بالهنبازين : ثم أرسله 3 والي البهنسا الذي بدوره ضربه بالمطارق الحديدية : وجلده حتى تأر ثر لحمه؛ ثم ربطوا )0 دعوشيه: إحدى بلاد الفيوم.\nأسياخ حديدية محماة بالنار في جسده؛ وكان الرب يسوع يشفيه ويعافيه وينقذه.\nولما احتار الوالي أمر بقطع رأسه بحذ السيف فال إكليل الشهادة. فأخذ بعض المؤمنين جسده وكفنوه بإكرام جزيل؛ ودفنوه في الموضع الذي كان يتعبد فيه.\nبركة صلواته فلتكن معنا. أمين.\n_ وفيه أ أيضا من. سنة للشهد ا ء) الكورة م 4 سس ستشهد. القد يس .\nإكليمنضس أسقف أنقرة '. ولد هذا القديس سنة في أنقرة» ومات أبوه الوثني وهو رضيع» فربته أمه المسيحية وأرضعته لبن الإيمان. وكان يحب الفقراء والمساكين ويهتم - الروحية والجسدية» ولنموه في الفضيلة رسموه شماسا » فازداد في تقواه ونسكه فأقاموه فقسا ثم صار أسقفا فيما بعد على أنقرة» فأخذ يجاهد في سبيل رعيته بمحبة باذلة ذاع صيت هذا القديس فسمع به الإمبراطور دقلديانوس فأمر والي غلاطية بالقبض عليه وعرض عليه أن يسجد للأوثان فرفض» فأمر بتعذيبه وتمزيق جسده بمخالب حديدية؛ ورشقه ثم ألقاه في السجن.\nاحتار الوالي في تعذيب القديس» فأرسلله إلى الإمبراطور» الذي لأظفه كثيرا محاولا أن ينكر إيمانه» ولما لم يستطع أن يثنيه ''؟ أنقرة: بإقليم غلاطية بآسيا الصغرى» وهي الآن عاصمة تركيا.\nعن إمانه» أمر بتمزيق جسده في دولاب حديدي به أسنان .\nوكان الرب ينقذه حتى آمن كثير من الوثنيين. وقد تولى تعذيبه كثيرون حتى أنه أوقف أمام سبعة مجالس للحكم كان في أنقرة» وفي كل مرة كان يزداد تمسكا وقوة.\nوأخيرا قطعوا رأسه فنال إكليل الشهادة؛ وأخذت جسده امرأة مؤمنة اسمها صوفية ودفنته بإكرام جزيل.\nبركة صلواته فلتكن معنا. امين.\n- وفيه أيضا من سنة 17 للشهداء ( م ) استشهد القديس فيلياس أسقف تمى الأمديد ؟\nعريقة في تمي الأمديد» وتعلم الفلسفة والعلوم والآداب ونبغ فيها فعيضنه الإمبراطور واليا على منطقته. ونظرا لحياة التقوى والقداسة التي كان يعيشهاء ترك أعمال الولاية ورسم أسقفا على نفس الإيبارشية» فاهتم بالوعظ وتعليم الشعب وافتقاده؛ في طريق القداسة والثبات على الإيمان في فترة مضى القديس إلى الإسكندرية لينال بركة البابا القديس بطرس خاتم الشهداء» فرأى هناك عذابات شهداء الإسكندرية وكان يشددهم ويشجعهم» فقبض عليه الوالي وأودعه في السجن» فأرسل رسالة رعوية إلى شعب إيبارشيته يدعوهم أن ولد هذا القديس من أسرة 0 في الأمديد: حاليا قرية ممركز الستبلاوين محافظة الدقهلية.\nعن إمانه» أمر بتمزيق جسده في دولاب حديدي به أسنان يثبتوا على الإبمان ويحتملوا الآلام من أجل اسم المسيح ومن وكان الرب ينقذه حتى آمن كثير من الوثنيين. وقد تولى أجل أن ينالوا الحياة الأبدية السعيدة.\nتعذييه كثيرون حتى أنه أوقف أمام سبعة مجالس للحكم كان اقتيد إلى ساحة الاستشهاد وهناك مد ذراعيه على شكل في أنقرة» وفي كل مرة كان يزداد نمسكا وقوة. صليب وصلى بصوت عال» ثم ضرب الجند عنقه بحد السيف ,| وأخبرا قطعوا رأسه فدال إكليل الشهادة ي» وأخذت جسده فال إكليل الشهادة.\n\" امرأة مؤمنة اسبمها صوفية ودفنته بإكرام جزيل. | بركة صلواته فلتكن معنا. آمين. بركة صلواته فلتكن معنا.\n- وفيه أيضا من سنة 77 للشهداء ( م ) استشهد القديس ولربنا المجد دائما أبديا آمين.\nفيلياس أسقف تمي الأمديد ”\". ولد هذا القديس من أسرة | | عريقة ل في الأمديد وتعلم الفلسفة والعلوم والآداب ونبغ فيها فعيضنه إ لإمبراطور واليا على منطقته. ونظرا لحياة التقرى #“\" والقداسة التي كان يعيشهاء ترك أعمال الولاية ورسم أسقفا ' ا على نس الإبارشية 6 فاهتم بالوعظ وتعليم الشعب وافتقاده 6 طريق القداسة والثبات على الإيممان في فترة الاضطهاد. . إ القديس إلى الإسكندرية لينال بركة البابا القديس الشهداء» فرأى هناك عذابات شهداء الإسكندرية | وكان يشددهم ويشجعهم»؛ فقبض عليه الوالي وأودعه في ض السجن» فأرسل رسالة رعوية إلى شعب ليبارشيتة يدعوهم أن | تمي الأمديد: حاليا قرية بمركز السنبلاوين محافظة الدقهلية."},{"d":29,"t":["نياحة القديسة أكساني","نياحة القديس سرياكوس المجاهد","نياحة القديسة أكساني. الإسكندرية أنها علامة سماوية تدل على سمو حياتها الروحية"],"b":"- في مثل هذا اليوم تيحت القديسة أكساني. كانت ابنة وحيدة لأحد أشراف روما. نشأت محبة للعبادة وقراءة سير القديسين والعطف على المساكين. كانت تداوم على زيارة بيوت العذارى وتحاول أن تتمثل بهن. خطبها أحد أبناء وزراء روما فأعد والدها كل ما يلزم للعرس. أما هي فسألت والدتها أن تذهب لزيارة بعض الراهبات لتودعهن» ولما سبمحت لها أخذت اثنين من جواريها وكل خليها وأبحرت إلى قبرص حيث التقت بالقديس إبيفانيوس أسقف قبرص وأعلمته باشتياقها إلى حياة الرهبنة.\nفأشار إليها أن تذهب إلى الإسكندرية فأطاعت وأبحرت إلى الإسكندرية حيث التقت بالبابا ثاؤفيلس ( 77 ) وأطلعته على رغبتها وسلمته كل خلبها فضمها إلى أحد بيوت العذارى أما وبنى بثمنها كنيسة على اسم القديس إسطفانوس استمرت أكسانى تمارس حياة النسك والعبادة أكثر من عشرين عاما ولما جاء وقت نياحتها ظهر في السماء صليب من نور حوله دائرة مضيئة من النجوم وذلك في منتصف النهار اليوم التاسع والعشرون من شهر طوبه المبارك 0 اليوم التاسع والعشرون من شهر طوبه المبارك اليو التاسع والعثمرون من شهر طوبه المبارك! ض وظل هذا المنظر باقيا حتى دفن جسدها الطاهر فعرف أهل '- نياحة القديس سرياكوس المجاهد. بركة صلواتها فلتكن معنا. امين.\n0\" - في مثل هذا اليوم تشحت القديسة أكساني. كانت ابنة وحيدة 7 - وفيه أيضا تبح القديس سرياكوس الجاهد.\n' | لأحد أشراف روما. نشأت محبة للعبادة وقراءة سير القديسين :\n, | والعطف على المساكين. كانت تداوم على زيارة بيوت العذارى | بركة صلواته فتك معنا.\n\"0 وتحاول أن تتمثل بهن. خطبها أحد أبناء وزراء روما فأعد والدها زم سس ولربنا المجد دائما أبديا آمين.\n\"0 كل ما يلزم للعرس. أما هي فسألت والدتها أن تذهب لزيارة .| 0 ض بعض الراهبات لتودعهن ولما مرحت لما أخذت اثنين مئ جواريها وكل خليها وأبحرت إل قبرص حيث التقت بالقديس “\" إبيفانيوس أسقف قبرص وأعلمته باشتياقها إلى حياة الرهبنة.\n“\" فأشار إليها أن تذهب إلى الإسكندرية فأطاعت وأبحرت إلى \"0 الإسكندرية حيث التقت بالبابا ثاؤفيلس ( 7 ) وأطلعته على ' رغبتها وسلمته كل خليها فضمها إلى أحد بيوت العذارى أما وبنى بثمنها كنيسة على اسم القديس إسطفانوس استمرت أكسانى تمارس حياة النسك والعبادة أكثر من عشرين عاما ولما جاء وقت نياحتها ظهر في السماء صليب من نور حوله دائرة مضيئة من النجوم وذلك في منتتصف النهار 427 | ض ار"},{"d":30,"t":["استشهاد العذارى القديسات بيستنيس وهلبيس وأغابى ونياحة أمهن صوفية","نياحة البابا مينا الأول البطريرك السابع والأربعين من بطاركة الكرازة المرقسية","نياحة القديس إبراهيم الرهاوي المتوحد"],"b":"بم ممممبعددلءدء<د«م ىندم صحفت في مثل هذا اليوم استشهدت العذارى القديسات بيستيس وه ميسم وأغابي وأمهن صوفية الى كانت من عائلة شريفة بأنطاكية وقد رزقها الله هؤلاء البنات الثلاث فأسمتهن بيستيس أي إيمان وهلبيس أي رجاء وأغابي أي شحبة أما صوفية فمعناها مضت هذه ا لقديسة ببنا ها الثلاث إلى روما لتعلمهن العلوم الكنسية والعبادة فبلغ أمرهن إلى الملك أدريانوس وحاول أن يجبرهن على ترك الإيمان المسيحي فكانت أمهن تشجعهن على الثبات في الإيمان بالسيد المسيح حت يئلن أكاليل الشهادة؛ وكان عمر بيستيس سنة وهلبيس سنة وأغابى 9 سنوات» ولما رأى الملك تمسكهن بالإيمان مرق جسد بيستيس بالسياط وألقاها في أتون النار ثم قطع رأسها أما هلبيس فمشط جسدها بالأمشاط الحديدية ثم ضرب عنقها بالسيف» ولما جاء دور أغابى الصغيرة ووجدها متمسكة بالإيمان ولم ترتعب من قثل أختيها أمامها أمر بإلقائها في أتون النار ثم عصرها بالهنبازين وأخيرا قطع رأسها ففرحت جدا أمهن صوفية وتهللت وشكرت الرب على ثبات بناتها على الإبمان وأنمن نلن أكاليل الشهادة وصرن عرائس للسيد المسيح فأخذت أجسادهن ولفتهن بلشفائف ثمينة وطلبت إلى الرب أن يقبل روحها فسمع الله صلاتها واستودعت روحها الطاهرة في يدي الرب» فأخذ المؤمنون أجسادهن الطاهرة ودفنوها بإكرام جزيل. ض | بركة صلواتهن فلتكن معنا. امين.\n؟ - وفيه أيضا من سنة 447 للشهداء ) تنح البابا القديس الأنبا مينا الأول البطريرك السابع والأربحون من بطاركة الكرازة المرقسية. ولد هذا القديس في سمشود وتربى تربية مسيحية ولما كبر ترهب في دير القديس مكاريوس باسم الراهب ميناء ولما تنيح البابا خائيل الأول اجتمع الأساقفة والشعب واتفقوا على اختيار الراهب مينا لكثرة فضائله وعلمه وبعد أن جلس على السدة المرقسية اهتم برعاية شعبه وافتقاده كما بنى الكنائس التي تهدمت. وقد لحقته تجربة شديدة أثارها عليه أحد الرهبان الذي كان يريد أن يحصل على درجة الأسقفية بأي البابا لضغوط كثيرة بسبب هذا الأمر لكنه احتمل بصبر وشجاعة. ولما أكمل سعيه الصالح تنيح بسلام بعد أن جلس على الكرسى المرفقسي ثماني سنوات وعشرة شهور ودفن بالكنيسة المرقسية بالإسكندرية.\nبركة صلواته فلتكن معنا. آمين.\nوفيه أيضا تنيح القديس إبراهيم يم الرهاوي المتوحد. ولد بمديلة الرها من بلاد ما بين النهرين في بداية القرن الرابع الميلادي من على حياة التقنوى خبا للعبادة واشتاق إلى حياة الرهبنة وطلب كثيرا إلى الله أن يدبر أمر فسكن ف مغارة ف الجبل القريب من مدينته وظل أهله يبحثون عنه فوجدوه في المغارة فأرادوا أن يأخذوه معهم فرفض وطلب منهم ان لا يزوروه مرة اخرى . بعد مدة أغلق مغارته وترك فيها طاقة صغيرة يتنا ول منها طعامه وظل ف هذه - الوحدة نحو خمسين عاما فكان مثالا للمتوحدين بسيطأ للغاية في كان بالقرب منه قرية مملوءة بالوثنيين الأشرار ولم يستطع أحد من المسيحيين أن يدخل إليها لبر بالسيد المسيح فطلب القديس يعقوب السروجي أسقف المنطقة من القديس إبراهيم المتوحد أن يذهب إلى القرية ويبشر أهلها بالسيد المسيح فشعر قوى لهذه الخدمة . فخرج من مغارته ودخل إليها وبدأ فيها باسم السيد المسيح فاضطهده الوثنيون وضربوه خارج القرية. ظل خارج القرية يصلى إلى الله لكي يفتقدهم برحمته فاستجاب الله صلاته وحرك قلوبهم فذهبوا إليه فوعظهم بكلام الحياة الأبدية والإيمان بالرب يسوع المسيح فتأثر بعضهم وطلبوا منه الصفح عما أساءوا إليه وظلوا منه كلام الحياة حتى آمنوا باسم المسيح وطلبوا العماد.\nفأرسل إلى الأسقف يعلمه برغبة ة أهل القرية فاتى وعمد منهم عددا كثرا. وظل القديس إبراهيم يعلمهم وب يثبتهم في الإيمان مدة من الزمن. وأخرا عاد إلى مغارته ا حياة الوحدة كان لأخيه ابنة اسمها مريم مات أبواها وتركاها وحيدة | استطاع الشيطان أن ييسقطها في الخطية» فاستطاع بمعونة الرب أن يعيدها إلى حياة التوبة وسكنت فى مغارة مجاورة لمغارته 8 وسارت سيرة رهبانية حسنة.\nولما أكمل القديس إبراهيم يم المتوحد سعيه الصالح رقد في الرب بالغا من العمر 0 عاما.\nبركة صلواته فلتكن معنا.\nولربنا المجد دائما أيديا آمين."}];
